const e=(n,r,s)=>({es:n,pt:r,en:s}),a=(n,r,s,t,c,d,u,l,p,m=34)=>({id:n,title:r,duration:m,objectives:e(`Al finalizar, podrás explicar ${r.es.toLowerCase()}, aplicarlo a una decisión de diseño y justificar tu razonamiento con una evidencia o artefacto observable.`,`Ao finalizar, você poderá explicar ${r.pt.toLowerCase()}, aplicá-lo a uma decisão de design e justificar seu raciocínio com uma evidência ou artefato observável.`,`By the end, you can explain ${r.en.toLowerCase()}, apply it to a design decision, and justify your reasoning with observable evidence or an artifact.`),concept:s,why:t,workflow:c,example:d,mistake:u,exercise:l,professionalUse:p}),i=(n,r,s,t)=>({prompt:n,options:r,correctIndex:s,rationale:t}),v=[{id:"foundations",order:0,level:e("Nivel 0","Nível 0","Level 0"),title:e("Fundamentos de diseño","Fundamentos de design","Design foundations"),summary:e("Construye lenguaje visual, criterio y hábitos de observación antes de abrir una herramienta.","Construa repertório visual, critério e hábitos de observação antes de abrir uma ferramenta.","Build visual literacy, judgment, and observation habits before opening a design tool."),competencies:[e("Distinguir problema, interfaz y resultado","Distinguir problema, interface e resultado","Distinguish problem, interface, and outcome"),e("Observar fricciones sin asumir causas","Observar fricções sem presumir causas","Observe friction without assuming causes"),e("Explicar una decisión visual","Explicar uma decisão visual","Explain a visual decision")],caseStudy:e("Una clínica tiene citas perdidas. Antes de proponer recordatorios, separa síntomas observables, hipótesis y evidencia necesaria.","Uma clínica tem faltas às consultas. Antes de propor lembretes, separe sintomas observáveis, hipóteses e evidências necessárias.","A clinic has missed appointments. Before proposing reminders, separate observable symptoms, hypotheses, and required evidence."),guidedPractice:e("Fotografía o describe una tarea cotidiana de tres pasos. Marca dónde decides, esperas o dudas; nombra el indicio que observaste.","Fotografe ou descreva uma tarefa cotidiana de três passos. Marque onde decide, espera ou duvida; nomeie o indício observado.","Photograph or describe a three-step everyday task. Mark where you decide, wait, or hesitate; name the cue you observed."),individualPractice:e("Audita una pantalla conocida con la pregunta: ¿qué permite hacer, qué promete y qué evidencia ofrece?","Audite uma tela conhecida com a pergunta: o que ela permite fazer, o que promete e que evidência oferece?","Audit a familiar screen: what does it enable, promise, and provide evidence for?"),miniProject:e("Redacta una ficha de fricción para una tarea cotidiana con observación, supuesto, riesgo y pregunta de investigación.","Redija uma ficha de fricção para uma tarefa cotidiana com observação, suposição, risco e pergunta de pesquisa.","Write a friction brief for an everyday task with observation, assumption, risk, and research question."),rubricFocus:[e("Observación concreta","Observação concreta","Concrete observation"),e("Separación entre evidencia y opinión","Separação entre evidência e opinião","Evidence–opinion separation")],glossary:[{term:"UX",definition:e("Calidad de la experiencia de una persona al intentar lograr un objetivo.","Qualidade da experiência de uma pessoa ao tentar alcançar um objetivo.","Quality of a person's experience while trying to achieve a goal.")},{term:"Fricción",definition:e("Esfuerzo, confusión o demora que dificulta avanzar.","Esforço, confusão ou demora que dificulta avançar.","Effort, confusion, or delay that makes progress harder.")}],lessons:[a("f1",e("Diseñar es decidir bajo incertidumbre","Projetar é decidir sob incerteza","Design is deciding under uncertainty"),e("El diseño convierte una intención en una experiencia observable; no es solo decoración.","Design transforma uma intenção em uma experiência observável; não é apenas decoração.","Design turns an intention into an observable experience; it is not decoration alone."),e("Una pantalla atractiva puede seguir bloqueando una tarea. El criterio empieza al definir qué debe cambiar para quién.","Uma tela atraente ainda pode bloquear uma tarefa. O critério começa ao definir o que deve mudar e para quem.","An attractive screen can still block a task. Judgment starts by defining what must change and for whom."),e("Describe contexto, objetivo, acción y resultado; después identifica lo desconocido.","Descreva contexto, objetivo, ação e resultado; depois identifique o desconhecido.","Describe context, goal, action, and result; then identify what is unknown."),e("En una compra, 'pagar' es una acción; sentir seguridad al confirmar es parte de la experiencia.","Em uma compra, 'pagar' é uma ação; sentir segurança ao confirmar faz parte da experiência.","In a purchase, 'paying' is an action; feeling confident at confirmation is part of the experience."),e("Confundir una solución con el problema: 'necesitamos un chatbot' no explica la necesidad.","Confundir uma solução com o problema: 'precisamos de um chatbot' não explica a necessidade.","Mistaking a solution for the problem: 'we need a chatbot' does not explain the need."),e("Convierte una queja de servicio en una afirmación comprobable.","Converta uma reclamação de serviço em uma afirmação verificável.","Turn a service complaint into a testable statement."),e("En una revisión de producto, formula decisiones como hipótesis que la evidencia puede cambiar.","Em uma revisão de produto, formule decisões como hipóteses que a evidência pode mudar.","In a product review, frame decisions as hypotheses evidence can change.")),a("f2",e("Percepción, jerarquía y atención","Percepção, hierarquia e atenção","Perception, hierarchy, and attention"),e("La jerarquía ordena qué se ve y comprende primero mediante tamaño, contraste, posición y agrupación.","A hierarquia ordena o que se vê e compreende primeiro por tamanho, contraste, posição e agrupamento.","Hierarchy orders what is seen and understood first through size, contrast, position, and grouping."),e("Sin jerarquía, las personas comparan demasiadas señales y tardan en elegir.","Sem hierarquia, as pessoas comparam sinais demais e demoram a escolher.","Without hierarchy, people compare too many signals and take longer to choose."),e("Identifica la tarea primaria, reduce competidores visuales y comprueba el recorrido de lectura.","Identifique a tarefa primária, reduza concorrentes visuais e verifique o percurso de leitura.","Identify the primary task, reduce visual competitors, and check the reading path."),e("En una pantalla de pago, importe, método y confirmación requieren una secuencia inequívoca.","Em uma tela de pagamento, valor, método e confirmação exigem uma sequência inequívoca.","On a payment screen, amount, method, and confirmation require an unambiguous sequence."),e("Usar color como único canal de prioridad o error.","Usar cor como único canal de prioridade ou erro.","Using color as the only channel for priority or error."),e("Reordena una pantalla saturada en tres niveles de importancia y justifica cada cambio.","Reordene uma tela carregada em três níveis de importância e justifique cada mudança.","Reorder a crowded screen into three importance levels and justify each change."),e("Explica la jerarquía en una anotación de diseño para ingeniería y stakeholders.","Explique a hierarquia em uma anotação de design para engenharia e stakeholders.","Explain hierarchy in a design annotation for engineering and stakeholders.")),a("f3",e("Vocabulario para colaborar","Vocabulário para colaborar","Vocabulary for collaboration"),e("Los equipos trabajan mejor cuando diferencian flujo, pantalla, componente, estado y métrica.","As equipes trabalham melhor quando diferenciam fluxo, tela, componente, estado e métrica.","Teams work better when they distinguish flow, screen, component, state, and metric."),e("Un nombre preciso evita que diseño, producto e ingeniería discutan objetos distintos.","Um nome preciso evita que design, produto e engenharia discutam objetos diferentes.","Precise naming prevents design, product, and engineering from debating different objects."),e("Define cada término con un ejemplo de tu proyecto y úsalo de manera consistente.","Defina cada termo com um exemplo do seu projeto e use-o de forma consistente.","Define each term with an example from your project and use it consistently."),e("'Error de formulario' es un estado; 'registro' es un flujo compuesto por pantallas y componentes.","'Erro de formulário' é um estado; 'cadastro' é um fluxo composto por telas e componentes.","'Form error' is a state; 'sign-up' is a flow made of screens and components."),e("Llamar 'UI' a cualquier decisión de experiencia, incluso a una hipótesis de negocio.","Chamar qualquer decisão de experiência de 'UI', inclusive uma hipótese de negócio.","Calling every experience decision 'UI,' including a business hypothesis."),e("Crea un glosario de diez términos que usarás en tu primer proyecto.","Crie um glossário de dez termos que usará no seu primeiro projeto.","Create a glossary of ten terms you will use in your first project."),e("Usa el glosario en una sesión de handoff o retroalimentación para reducir ambigüedad.","Use o glossário em uma sessão de handoff ou feedback para reduzir ambiguidade.","Use the glossary in a handoff or feedback session to reduce ambiguity."))],quiz:[i(e("¿Qué enunciado describe mejor una fricción?","Qual enunciado descreve melhor uma fricção?","Which statement best describes friction?"),[e("Una preferencia estética","Uma preferência estética","An aesthetic preference"),e("Un esfuerzo o confusión que interrumpe un objetivo","Um esforço ou confusão que interrompe um objetivo","Effort or confusion interrupting a goal"),e("El nombre de una pantalla","O nome de uma tela","The name of a screen")],1,e("La fricción se observa como dificultad para avanzar, no como gusto personal.","A fricção é observada como dificuldade para avançar, não como gosto pessoal.","Friction is observed as difficulty progressing, not personal taste."))]},{id:"ux-fundamentals",order:1,level:e("Nivel 1","Nível 1","Level 1"),title:e("UX Fundamentals","UX Fundamentals","UX Fundamentals"),summary:e("Relaciona necesidades humanas, objetivos de negocio y restricciones técnicas en decisiones de experiencia.","Relacione necessidades humanas, objetivos de negócio e restrições técnicas em decisões de experiência.","Connect human needs, business goals, and technical constraints in experience decisions."),competencies:[e("Mapear un flujo","Mapear um fluxo","Map a flow"),e("Formular hipótesis","Formular hipóteses","Formulate hypotheses"),e("Explicar iteración","Explicar iteração","Explain iteration")],caseStudy:e("Una biblioteca digital tiene muchas descargas pero pocas renovaciones. Distingue el síntoma de las necesidades que deben investigarse.","Uma biblioteca digital tem muitos downloads, mas poucas renovações. Distinga o sintoma das necessidades a investigar.","A digital library has many downloads but few renewals. Distinguish the symptom from needs worth investigating."),guidedPractice:e("Dibuja el camino actual para renovar un préstamo y señala dependencias, decisiones y estados.","Desenhe o caminho atual para renovar um empréstimo e sinalize dependências, decisões e estados.","Draw the current path for renewing a loan and mark dependencies, decisions, and states."),individualPractice:e("Formula tres hipótesis competidoras para una caída de renovación.","Formule três hipóteses concorrentes para uma queda de renovação.","Formulate three competing hypotheses for a renewal decline."),miniProject:e("Produce un mapa de experiencia de una tarea con objetivo, punto de dolor, oportunidad y medida de éxito.","Produza um mapa de experiência de uma tarefa com objetivo, ponto de dor, oportunidade e medida de sucesso.","Produce an experience map for a task with goal, pain point, opportunity, and success measure."),rubricFocus:[e("Trazabilidad de hipótesis","Rastreabilidade de hipóteses","Hypothesis traceability"),e("Claridad de flujo","Clareza do fluxo","Flow clarity")],glossary:[{term:"Hipótesis",definition:e("Explicación provisional que puede probarse.","Explicação provisória que pode ser testada.","A provisional explanation that can be tested.")}],lessons:[a("u1",e("Diseño centrado en personas","Design centrado nas pessoas","Human-centered design"),e("Diseñar con enfoque humano parte de entender el contexto de uso antes de elegir una solución.","Projetar com foco humano parte de entender o contexto de uso antes de escolher uma solução.","Human-centered design starts by understanding use context before choosing a solution."),e("Reduce el riesgo de optimizar para supuestos internos.","Reduz o risco de otimizar para suposições internas.","It reduces the risk of optimizing for internal assumptions."),e("Formula una necesidad, busca evidencia y decide la intervención más pequeña que puede aprender algo.","Formule uma necessidade, busque evidência e decida a menor intervenção que pode ensinar algo.","State a need, seek evidence, and choose the smallest intervention that can teach something."),e("Una persona no quiere una 'cuenta'; quiere retomar una reserva sin repetir datos.","Uma pessoa não quer uma 'conta'; quer retomar uma reserva sem repetir dados.","A person does not want an 'account'; they want to resume a booking without repeating data."),e("Preguntar solo qué función quiere alguien, sin explorar el contexto.","Perguntar apenas que função alguém quer, sem explorar o contexto.","Asking only which feature someone wants without exploring context."),e("Reescribe una solicitud de funcionalidad como necesidad, contexto y resultado esperado.","Reescreva uma solicitação de funcionalidade como necessidade, contexto e resultado esperado.","Rewrite a feature request as need, context, and expected outcome."),e("Presenta decisiones usando evidencia de necesidad en lugar de preferencias del equipo.","Apresente decisões usando evidência de necessidade em vez de preferências da equipe.","Present decisions using evidence of need rather than team preferences.")),a("u2",e("Procesos que vuelven a empezar","Processos que recomeçam","Processes that loop"),e("Empatizar, definir, idear, prototipar y probar son actividades conectadas, no una escalera rígida.","Empatizar, definir, idear, prototipar e testar são atividades conectadas, não uma escada rígida.","Empathize, define, ideate, prototype, and test are connected activities, not a rigid staircase."),e("La nueva evidencia puede cambiar tanto el problema como la interfaz.","A nova evidência pode mudar tanto o problema quanto a interface.","New evidence can change both the problem and the interface."),e("Mantén una pregunta de aprendizaje por iteración y decide qué artefacto basta para responderla.","Mantenha uma pergunta de aprendizagem por iteração e decida qual artefato basta para respondê-la.","Keep one learning question per iteration and decide which artifact is enough to answer it."),e("Un prototipo en papel puede ser suficiente para saber si una secuencia se entiende.","Um protótipo em papel pode bastar para saber se uma sequência é compreendida.","A paper prototype can be enough to learn whether a sequence is understood."),e("Crear alta fidelidad antes de saber qué comportamiento se necesita probar.","Criar alta fidelidade antes de saber qual comportamento precisa ser testado.","Creating high fidelity before knowing which behavior needs testing."),e("Selecciona fidelidad baja, media o alta para tres preguntas de aprendizaje distintas.","Selecione fidelidade baixa, média ou alta para três perguntas de aprendizagem distintas.","Select low, medium, or high fidelity for three different learning questions."),e("En discovery, declara qué incertidumbre reduce cada entrega.","Em discovery, declare qual incerteza cada entrega reduz.","In discovery, state which uncertainty each deliverable reduces.")),a("u3",e("Roles y decisiones compartidas","Papéis e decisões compartilhadas","Roles and shared decisions"),e("Producto define resultados, diseño explora la experiencia e ingeniería evalúa factibilidad; los límites se solapan.","Produto define resultados, design explora a experiência e engenharia avalia viabilidade; os limites se sobrepõem.","Product defines outcomes, design explores experience, and engineering evaluates feasibility; boundaries overlap."),e("Las decisiones mejoran cuando las perspectivas se encuentran antes del handoff.","As decisões melhoram quando as perspectivas se encontram antes do handoff.","Decisions improve when perspectives meet before handoff."),e("Convoca una revisión con objetivo, evidencia disponible, decisiones pendientes y restricciones explícitas.","Convide para uma revisão com objetivo, evidência disponível, decisões pendentes e restrições explícitas.","Run a review with goal, available evidence, open decisions, and explicit constraints."),e("Un ingeniero puede detectar un estado técnico que altera el flujo y requiere rediseño.","Uma pessoa de engenharia pode detectar um estado técnico que altera o fluxo e exige redesenho.","An engineer may identify a technical state that alters a flow and requires redesign."),e("Tratar el handoff como el único momento de colaboración.","Tratar o handoff como o único momento de colaboração.","Treating handoff as the only moment of collaboration."),e("Prepara una agenda de revisión para un flujo de registro.","Prepare uma pauta de revisão para um fluxo de cadastro.","Prepare a review agenda for a sign-up flow."),e("Documenta decisiones, dueños y riesgos para evitar que el diseño sea una imagen aislada.","Documente decisões, responsáveis e riscos para evitar que o design seja uma imagem isolada.","Document decisions, owners, and risks to prevent design from becoming an isolated image."))],quiz:[i(e("¿Cuándo conviene volver a definir el problema?","Quando convém voltar a definir o problema?","When should you revisit the problem definition?"),[e("Nunca, una vez aprobado","Nunca, depois de aprovado","Never, once approved"),e("Cuando nueva evidencia contradice el supuesto inicial","Quando nova evidência contradiz a suposição inicial","When new evidence contradicts the initial assumption"),e("Solo al final de desarrollo","Apenas no final do desenvolvimento","Only at the end of development")],1,e("La iteración puede afectar la definición, no únicamente el acabado.","A iteração pode afetar a definição, não apenas o acabamento.","Iteration can affect definition, not only polish."))]},{id:"research",order:2,level:e("Nivel 2","Nível 2","Level 2"),title:e("User Research","User Research","User Research"),summary:e("Planifica investigación proporcional a la decisión que debe tomarse y sintetiza hallazgos accionables.","Planeje pesquisa proporcional à decisão a tomar e sintetize achados acionáveis.","Plan research proportional to the decision at stake and synthesize actionable findings."),competencies:[e("Redactar preguntas de investigación","Redigir perguntas de pesquisa","Write research questions"),e("Elegir método","Escolher método","Choose a method"),e("Sintetizar evidencia","Sintetizar evidências","Synthesize evidence")],caseStudy:e("El checkout tiene abandono alto. Decide qué se puede aprender con analítica, entrevista y prueba de usabilidad, y qué no.","O checkout tem alto abandono. Decida o que se aprende com analytics, entrevista e teste de usabilidade, e o que não.","Checkout abandonment is high. Decide what analytics, interviews, and usability testing can and cannot reveal."),guidedPractice:e("Convierte una pregunta amplia en objetivo, preguntas de investigación, participantes, método y decisión esperada.","Converta uma pergunta ampla em objetivo, perguntas de pesquisa, participantes, método e decisão esperada.","Turn a broad question into goal, research questions, participants, method, and expected decision."),individualPractice:e("Escribe una guía de entrevista de ocho preguntas no inductivas sobre una compra reciente.","Escreva um roteiro de entrevista de oito perguntas não indutivas sobre uma compra recente.","Write an eight-question non-leading interview guide about a recent purchase."),miniProject:e("Entrega un research plan con reclutamiento, ética, guion, matriz de notas y criterio de síntesis.","Entregue um research plan com recrutamento, ética, roteiro, matriz de notas e critério de síntese.","Deliver a research plan with recruitment, ethics, script, note matrix, and synthesis criterion."),rubricFocus:[e("Adecuación método-pregunta","Adequação método-pergunta","Method-question fit"),e("Neutralidad y trazabilidad","Neutralidade e rastreabilidade","Neutrality and traceability")],glossary:[{term:"Insight",definition:e("Interpretación respaldada por evidencia que cambia una decisión.","Interpretação respaldada por evidência que muda uma decisão.","Evidence-backed interpretation that changes a decision.")}],lessons:[a("r1",e("Preguntas antes que métodos","Perguntas antes de métodos","Questions before methods"),e("La elección de método parte de la decisión que necesita evidencia, no de la herramienta disponible.","A escolha do método parte da decisão que precisa de evidência, não da ferramenta disponível.","Method choice starts with the decision needing evidence, not the available tool."),e("Evita acumular datos que no alteran una acción de producto.","Evita acumular dados que não alteram uma ação de produto.","It prevents collecting data that does not alter a product action."),e("Escribe decisión, incertidumbre, pregunta, señal, método y límite de interpretación.","Escreva decisão, incerteza, pergunta, sinal, método e limite de interpretação.","Write decision, uncertainty, question, signal, method, and interpretation limit."),e("Para entender dónde se pierde un flujo se observa comportamiento; para estimar alcance se mide.","Para entender onde um fluxo falha, observe comportamento; para estimar alcance, meça.","To understand where a flow fails, observe behavior; to estimate scale, measure."),e("Elegir encuesta para descubrir por qué alguien duda durante una tarea compleja.","Escolher pesquisa para descobrir por que alguém hesita durante uma tarefa complexa.","Choosing a survey to discover why someone hesitates during a complex task."),e("Relaciona cuatro decisiones con el método mínimo que puede informarlas.","Relacione quatro decisões ao menor método que pode informá-las.","Match four decisions to the smallest method that can inform them."),e("Defiende el alcance de una investigación ante un stakeholder con tiempo limitado.","Defenda o escopo de uma pesquisa diante de um stakeholder com tempo limitado.","Defend research scope to a time-constrained stakeholder.")),a("r2",e("Entrevistas, observación y ética","Entrevistas, observação e ética","Interviews, observation, and ethics"),e("Las entrevistas recuperan relatos y la observación registra comportamiento; ambas requieren consentimiento e intención clara.","Entrevistas recuperam relatos e observação registra comportamento; ambas exigem consentimento e intenção clara.","Interviews elicit stories and observation records behavior; both require consent and clear intent."),e("La calidad del dato depende de no presionar, inducir ni recolectar información innecesaria.","A qualidade do dado depende de não pressionar, induzir ou coletar informação desnecessária.","Data quality depends on not pressuring, leading, or collecting unnecessary information."),e("Pide consentimiento, usa preguntas sobre hechos pasados, pausa ante incomodidad y separa notas de interpretación.","Peça consentimento, use perguntas sobre fatos passados, pause diante de desconforto e separe notas de interpretação.","Obtain consent, ask about past events, pause around discomfort, and separate notes from interpretation."),e("'Cuéntame la última vez que...' reduce especulación frente a '¿usarías...?'.","'Conte-me a última vez que...' reduz especulação em comparação com 'você usaria...?'.","'Tell me about the last time…' reduces speculation compared with 'would you use…?'."),e("Prometer privacidad sin explicar qué se guardará o usar preguntas que contienen la respuesta deseada.","Prometer privacidade sem explicar o que será guardado ou usar perguntas que contêm a resposta desejada.","Promising privacy without explaining storage or asking questions that contain the desired answer."),e("Revisa un guion y elimina tres formulaciones inductivas.","Revise um roteiro e elimine três formulações indutivas.","Review a script and remove three leading formulations."),e("Diseña estudios que respeten el tiempo, dignidad y datos de participantes.","Desenhe estudos que respeitem o tempo, a dignidade e os dados dos participantes.","Design studies that respect participants’ time, dignity, and data.")),a("r3",e("Síntesis que conduce a decisiones","Síntese que leva a decisões","Synthesis that leads to decisions"),e("Sintetizar agrupa observaciones, identifica patrones y declara su confianza sin borrar excepciones.","Sintetizar agrupa observações, identifica padrões e declara sua confiança sem apagar exceções.","Synthesis groups observations, identifies patterns, and states confidence without erasing exceptions."),e("Un muro de notas no cambia un producto hasta que se conecta con una oportunidad o decisión.","Um mural de notas não muda um produto até se conectar a uma oportunidade ou decisão.","A wall of notes does not change a product until it connects to an opportunity or decision."),e("Codifica evidencia, agrupa por significado, formula hallazgo y enlázalo con una recomendación verificable.","Codifique evidências, agrupe por significado, formule achado e conecte-o a uma recomendação verificável.","Code evidence, group by meaning, formulate a finding, and link it to a testable recommendation."),e("Tres personas que pierden una confirmación sugieren revisar visibilidad; no prueban que el color sea la causa.","Três pessoas que perdem uma confirmação sugerem revisar visibilidade; não provam que a cor seja a causa.","Three people missing a confirmation suggest reviewing visibility; they do not prove color is the cause."),e("Convertir una cita aislada en una conclusión universal.","Transformar uma citação isolada em uma conclusão universal.","Turning an isolated quote into a universal conclusion."),e("Construye tres hallazgos con evidencia, implicación y siguiente pregunta.","Construa três achados com evidência, implicação e próxima pergunta.","Build three findings with evidence, implication, and next question."),e("Entrega un readout que permita decidir qué explorar, cambiar o no hacer.","Entregue um readout que permita decidir o que explorar, mudar ou não fazer.","Deliver a readout that enables decisions about what to explore, change, or not do."))],quiz:[i(e("¿Qué debe guiar la selección de un método?","O que deve guiar a seleção de um método?","What should guide method selection?"),[e("La herramienta más conocida","A ferramenta mais conhecida","The most familiar tool"),e("La decisión y la incertidumbre que se busca reducir","A decisão e a incerteza que se busca reduzir","The decision and uncertainty to reduce"),e("La opinión del primer participante","A opinião da primeira pessoa participante","The first participant’s opinion")],1,e("El método se selecciona por la pregunta y decisión, no por costumbre.","O método é selecionado pela pergunta e decisão, não por costume.","A method is selected for the question and decision, not habit."))]},{id:"define-ideate",order:3,level:e("Nivel 3","Nível 3","Level 3"),title:e("Define & Ideate","Define & Ideate","Define & Ideate"),summary:e("Traduce evidencia en oportunidades, criterios y alternativas que pueden evaluarse.","Traduza evidências em oportunidades, critérios e alternativas que podem ser avaliadas.","Translate evidence into opportunities, criteria, and alternatives that can be evaluated."),competencies:[e("Crear personas útiles","Criar personas úteis","Create useful personas"),e("Escribir problem statements","Escrever problem statements","Write problem statements"),e("Facilitar ideación","Facilitar ideação","Facilitate ideation")],caseStudy:e("Usuarios de un servicio de salud abandonan antes de elegir especialista. Crea una oportunidad sin prescribir la solución.","Usuários de um serviço de saúde desistem antes de escolher especialista. Crie uma oportunidade sem prescrever a solução.","Health-service users leave before choosing a specialist. Create an opportunity without prescribing the solution."),guidedPractice:e("Agrupa observaciones de investigación y convierte un patrón en una tensión que el producto podría resolver.","Agrupe observações de pesquisa e converta um padrão em uma tensão que o produto poderia resolver.","Group research observations and turn a pattern into a tension the product could address."),individualPractice:e("Escribe cinco preguntas How Might We con distinto alcance y selecciona una con criterio.","Escreva cinco perguntas How Might We com escopos diferentes e selecione uma com critério.","Write five How Might We questions at different scopes and choose one with a criterion."),miniProject:e("Entrega una persona basada en evidencia, journey, problem statement y tres hipótesis de solución.","Entregue uma persona baseada em evidência, jornada, problem statement e três hipóteses de solução.","Deliver an evidence-based persona, journey, problem statement, and three solution hypotheses."),rubricFocus:[e("Fidelidad a evidencia","Fidelidade às evidências","Fidelity to evidence"),e("Apertura de alternativas","Abertura de alternativas","Breadth of alternatives")],glossary:[{term:"How Might We",definition:e("Pregunta que transforma una tensión en espacio de ideación.","Pergunta que transforma uma tensão em espaço de ideação.","Question that turns a tension into an ideation space.")}],lessons:[a("d1",e("De hallazgos a oportunidades","De achados a oportunidades","From findings to opportunities"),e("Una oportunidad describe una necesidad o tensión respaldada; no contiene una interfaz preseleccionada.","Uma oportunidade descreve uma necessidade ou tensão respaldada; não contém uma interface pré-selecionada.","An opportunity describes an evidence-backed need or tension; it contains no preselected interface."),e("Mantiene varias rutas de solución abiertas y reduce la defensa prematura de ideas.","Mantém várias rotas de solução abertas e reduz a defesa prematura de ideias.","It keeps multiple solution paths open and reduces premature idea defense."),e("Conecta patrón, contexto, impacto y oportunidad de aprendizaje.","Conecte padrão, contexto, impacto e oportunidade de aprendizagem.","Connect pattern, context, impact, and learning opportunity."),e("'No sé qué especialista elegir' puede convertirse en una oportunidad de comparar pertinencia sin abrumar.","'Não sei qual especialista escolher' pode virar uma oportunidade de comparar pertinência sem sobrecarregar.","'I do not know which specialist to choose' can become an opportunity to compare relevance without overload."),e("Escribir 'agregar filtros' como hallazgo.","Escrever 'adicionar filtros' como achado.","Writing 'add filters' as a finding."),e("Distingue tres soluciones de la oportunidad que pretenden resolver.","Diferencie três soluções da oportunidade que pretendem resolver.","Separate three solutions from the opportunity they intend to address."),e("Prioriza oportunidades con impacto esperado, evidencia y coste de aprendizaje.","Priorize oportunidades com impacto esperado, evidência e custo de aprendizagem.","Prioritize opportunities with expected impact, evidence, and learning cost.")),a("d2",e("Personas y journeys con propósito","Personas e jornadas com propósito","Purposeful personas and journeys"),e("Una persona resume patrones relevantes de comportamiento, objetivo y limitación; no es una biografía inventada.","Uma persona resume padrões relevantes de comportamento, objetivo e limitação; não é uma biografia inventada.","A persona summarizes relevant behavioral patterns, goals, and constraints; it is not an invented biography."),e("Ayuda a mantener decisiones enfocadas cuando el equipo no comparte la misma cercanía con usuarios.","Ajuda a manter decisões focadas quando a equipe não compartilha a mesma proximidade com usuários.","It helps keep decisions focused when the team does not share the same closeness to users."),e("Selecciona evidencia, redacta necesidades, traza fases y marca emociones, obstáculos y oportunidades.","Selecione evidências, redija necessidades, trace fases e marque emoções, obstáculos e oportunidades.","Select evidence, write needs, map phases, and mark emotions, obstacles, and opportunities."),e("La fase 'comparar' puede incluir buscar recomendaciones, abrir perfiles y abandonar por información incompleta.","A fase 'comparar' pode incluir buscar recomendações, abrir perfis e desistir por informação incompleta.","The 'compare' phase can include seeking recommendations, opening profiles, and leaving because information is incomplete."),e("Añadir edad, foto o gustos sin evidencia ni decisión asociada.","Adicionar idade, foto ou gostos sem evidência nem decisão associada.","Adding age, photo, or hobbies without evidence or decision relevance."),e("Elimina elementos decorativos de una persona y justifica los que permanecen.","Elimine elementos decorativos de uma persona e justifique os que permanecem.","Remove decorative elements from a persona and justify what remains."),e("Usa journeys para alinear puntos de intervención entre servicio, contenido y producto.","Use jornadas para alinhar pontos de intervenção entre serviço, conteúdo e produto.","Use journeys to align intervention points across service, content, and product.")),a("d3",e("Ideación con criterios","Ideação com critérios","Ideation with criteria"),e("Idear produce alternativas; seleccionar exige criterios de deseabilidad, viabilidad, factibilidad, usabilidad y riesgo ético.","Idear produz alternativas; selecionar exige critérios de desejabilidade, viabilidade, factibilidade, usabilidade e risco ético.","Ideation produces alternatives; selection requires desirability, viability, feasibility, usability, and ethical-risk criteria."),e("Evita confundir muchas ideas con una buena decisión.","Evita confundir muitas ideias com uma boa decisão.","It prevents confusing many ideas with a good decision."),e("Genera en divergencia, agrupa, establece criterios, evalúa supuestos y define el siguiente experimento.","Gere em divergência, agrupe, estabeleça critérios, avalie suposições e defina o próximo experimento.","Generate divergently, group, set criteria, assess assumptions, and define the next experiment."),e("Dos ideas pueden puntuar igual en deseo, pero una requerir datos sensibles y aumentar riesgo.","Duas ideias podem pontuar igual em desejo, mas uma exigir dados sensíveis e aumentar risco.","Two ideas may score equally on desire, but one may require sensitive data and raise risk."),e("Votar por la interfaz más vistosa sin declarar el criterio de votación.","Votar na interface mais vistosa sem declarar o critério de votação.","Voting for the flashiest interface without stating the voting criterion."),e("Realiza un Crazy 8s y evalúa tres propuestas con una matriz de criterios.","Faça um Crazy 8s e avalie três propostas com uma matriz de critérios.","Run a Crazy 8s and evaluate three proposals with a criteria matrix."),e("Facilita sesiones donde las ideas son hipótesis, no identidades personales.","Facilite sessões nas quais ideias são hipóteses, não identidades pessoais.","Facilitate sessions where ideas are hypotheses, not personal identities."))],quiz:[i(e("¿Qué hace útil a una persona?","O que torna uma persona útil?","What makes a persona useful?"),[e("Detalles demográficos abundantes","Detalhes demográficos abundantes","Abundant demographic detail"),e("Patrones de objetivo y limitación respaldados por evidencia","Padrões de objetivo e limitação respaldados por evidência","Evidence-backed goal and constraint patterns"),e("Una fotografía atractiva","Uma fotografia atraente","An attractive photo")],1,e("La persona debe informar decisiones, no decorar una presentación.","A persona deve informar decisões, não decorar uma apresentação.","A persona should inform decisions, not decorate a presentation."))]}],o=n=>({...n,quiz:[n.quiz]});v.push(o({id:"information-architecture",order:4,level:e("Nivel 4","Nível 4","Level 4"),title:e("Arquitectura de información","Arquitetura da informação","Information architecture"),summary:e("Organiza contenidos y navegación a partir de modelos mentales verificables.","Organize conteúdos e navegação a partir de modelos mentais verificáveis.","Organize content and navigation from testable mental models."),competencies:[e("Estructurar contenidos","Estruturar conteúdos","Structure content"),e("Diseñar navegación","Desenhar navegação","Design navigation")],caseStudy:e("Las personas no encuentran la configuración de privacidad de una app. Decide si el problema está en la etiqueta, la agrupación o la jerarquía.","As pessoas não encontram a configuração de privacidade de um app. Decida se o problema está no rótulo, agrupamento ou hierarquia.","People cannot find an app’s privacy settings. Decide whether the issue is label, grouping, or hierarchy."),guidedPractice:e("Agrupa quince tarjetas de contenido, nombra categorías y compara tu estructura con la de otra persona.","Agrupe quinze cartões de conteúdo, nomeie categorias e compare sua estrutura com a de outra pessoa.","Group fifteen content cards, name categories, and compare your structure with another person’s."),individualPractice:e("Diseña el árbol de navegación y tres tareas de tree testing para un portal de salud.","Desenhe a árvore de navegação e três tarefas de tree testing para um portal de saúde.","Design a navigation tree and three tree-testing tasks for a health portal."),miniProject:e("Define la arquitectura y el flujo de búsqueda de Civic Desk, justificando etiquetas y profundidad.","Defina a arquitetura e o fluxo de busca do Civic Desk, justificando rótulos e profundidade.","Define Civic Desk’s architecture and search flow, justifying labels and depth."),rubricFocus:[e("Modelos mentales","Modelos mentais","Mental models"),e("Encontrabilidad","Encontrabilidade","Findability")],glossary:[{term:"Tree testing",definition:e("Prueba de encontrabilidad sobre una jerarquía sin interfaz visual.","Teste de encontrabilidade sobre uma hierarquia sem interface visual.","Findability test of a hierarchy without visual interface.")}],lessons:[a("ia1",e("Categorías que reflejan modelos mentales","Categorias que refletem modelos mentais","Categories that reflect mental models"),e("La arquitectura de información convierte un espacio de contenidos en una estructura que las personas pueden recorrer y predecir.","A arquitetura da informação transforma um espaço de conteúdos em uma estrutura que as pessoas podem percorrer e prever.","Information architecture turns a content space into a structure people can traverse and predict."),e("Una navegación lógica para el equipo puede ser opaca para quien no conoce su organización interna.","Uma navegação lógica para a equipe pode ser opaca para quem não conhece sua organização interna.","Navigation logical to the team can be opaque to someone who does not know its internal organization."),e("Inventaría contenido, identifica tareas, agrupa por significado de usuario, nombra sin jerga y prueba rutas críticas.","Inventarie conteúdo, identifique tarefas, agrupe por significado do usuário, nomeie sem jargão e teste rotas críticas.","Inventory content, identify tasks, group by user meaning, label without jargon, and test critical paths."),e("'Cuenta' puede ocultar facturas, datos personales y seguridad; la tarea orienta la agrupación.","'Conta' pode ocultar faturas, dados pessoais e segurança; a tarefa orienta o agrupamento.","'Account' can hide bills, personal data, and security; the task guides grouping."),e("Copiar la estructura del organigrama en vez de la forma en que las personas buscan.","Copiar a estrutura do organograma em vez da forma como as pessoas buscam.","Copying the org chart instead of the way people seek information."),e("Renombra cinco secciones internas para que describan una tarea o resultado.","Renomeie cinco seções internas para que descrevam uma tarefa ou resultado.","Rename five internal sections to describe a task or outcome."),e("Antes de una navegación global, valida etiquetas con usuarios o evidencia de búsqueda.","Antes de uma navegação global, valide rótulos com usuários ou evidência de busca.","Before global navigation, validate labels with users or search evidence.")),a("ia2",e("Navegación, búsqueda y validación","Navegação, busca e validação","Navigation, search, and validation"),e("La navegación apoya exploración; la búsqueda apoya acceso directo. Las dos deben describir el mismo mundo de contenido.","A navegação apoia exploração; a busca apoia acesso direto. Ambas devem descrever o mesmo mundo de conteúdo.","Navigation supports exploration; search supports direct access. Both should describe the same content world."),e("Cuando etiquetas, filtros y resultados discrepan, la persona pierde confianza y necesita volver atrás.","Quando rótulos, filtros e resultados divergem, a pessoa perde confiança e precisa voltar.","When labels, filters, and results conflict, people lose confidence and must backtrack."),e("Define tareas prioritarias, diseña rutas, crea una jerarquía mínima y prueba si alguien llega sin pistas visuales.","Defina tarefas prioritárias, desenhe rotas, crie uma hierarquia mínima e teste se alguém chega sem pistas visuais.","Define priority tasks, design routes, create a minimal hierarchy, and test whether someone arrives without visual cues."),e("Si una tarea es 'encontrar una cita pasada', prueba tanto 'Historial' como la búsqueda por fecha.","Se uma tarefa é 'encontrar uma consulta passada', teste tanto 'Histórico' quanto a busca por data.","If the task is 'find a past appointment,' test both 'History' and date search."),e("Asumir que un icono de lupa corrige una estructura que nadie entiende.","Presumir que um ícone de lupa corrige uma estrutura que ninguém entende.","Assuming a magnifying-glass icon fixes a structure no one understands."),e("Redacta un protocolo de tree test con objetivo, tarea, éxito y seguimiento.","Redija um protocolo de tree test com objetivo, tarefa, sucesso e acompanhamento.","Write a tree-test protocol with goal, task, success, and follow-up."),e("Conecta resultados de encontrabilidad con cambios concretos de arquitectura, no con gustos sobre menús.","Conecte resultados de encontrabilidade a mudanças concretas de arquitetura, não a gostos sobre menus.","Connect findability results to concrete architecture changes, not menu preferences."))],quiz:i(e("¿Qué debe guiar una etiqueta de navegación?","O que deve guiar um rótulo de navegação?","What should guide a navigation label?"),[e("El nombre del departamento","O nome do departamento","The department name"),e("El modelo mental y la tarea de la persona","O modelo mental e a tarefa da pessoa","The person’s mental model and task"),e("La abreviatura más corta","A abreviação mais curta","The shortest abbreviation")],1,e("Las etiquetas deben ayudar a predecir dónde está una tarea o contenido.","Os rótulos devem ajudar a prever onde está uma tarefa ou conteúdo.","Labels should help predict where a task or content lives."))}),o({id:"wireframing",order:5,level:e("Nivel 5","Nível 5","Level 5"),title:e("Wireframing","Wireframing","Wireframing"),summary:e("Estructura flujos y pantallas de baja fidelidad para aprender antes de pulir.","Estruture fluxos e telas de baixa fidelidade para aprender antes de polir.","Structure low-fidelity flows and screens to learn before polishing."),competencies:[e("Priorizar contenido","Priorizar conteúdo","Prioritize content"),e("Anotar decisiones","Anotar decisões","Annotate decisions")],caseStudy:e("Pulse debe permitir registrar un hábito con una mano y sin perder el contexto del día. Define el flujo más pequeño que merece probarse.","Pulse deve permitir registrar um hábito com uma mão e sem perder o contexto do dia. Defina o menor fluxo que merece ser testado.","Pulse must let people log a habit one-handed without losing the day context. Define the smallest flow worth testing."),guidedPractice:e("Convierte un user flow de cuatro pasos en seis wireframes, incluyendo confirmación y recuperación de error.","Converta um user flow de quatro passos em seis wireframes, incluindo confirmação e recuperação de erro.","Turn a four-step user flow into six wireframes, including confirmation and error recovery."),individualPractice:e("Crea dos alternativas para la acción primaria y anota la hipótesis que cada una pone a prueba.","Crie duas alternativas para a ação principal e anote a hipótese que cada uma testa.","Create two alternatives for the primary action and annotate the hypothesis each tests."),miniProject:e("Entrega el flujo low-fi de Pulse con anotaciones de prioridad, estados y decisiones pendientes.","Entregue o fluxo low-fi do Pulse com anotações de prioridade, estados e decisões pendentes.","Deliver the Pulse low-fi flow with annotations for priority, states, and open decisions."),rubricFocus:[e("Flujo completo","Fluxo completo","Complete flow"),e("Economía de fidelidad","Economia de fidelidade","Fidelity economy")],glossary:[{term:"Wireframe",definition:e("Representación estructural de una pantalla o flujo, centrada en contenido y comportamiento.","Representação estrutural de uma tela ou fluxo, centrada em conteúdo e comportamento.","Structural representation of a screen or flow focused on content and behavior.")}],lessons:[a("w1",e("Fidelidad al servicio del aprendizaje","Fidelidade a serviço da aprendizagem","Fidelity in service of learning"),e("Un wireframe elimina decisiones visuales para exponer orden, contenido, interacción y estado.","Um wireframe remove decisões visuais para expor ordem, conteúdo, interação e estado.","A wireframe removes visual decisions to expose order, content, interaction, and state."),e("Permite descartar una mala secuencia antes de invertir tiempo en acabados.","Permite descartar uma sequência ruim antes de investir tempo em acabamento.","It allows a poor sequence to be discarded before investing time in polish."),e("Parte de un flujo, dibuja pantallas mínimas, declara acciones y documenta qué debe cambiar tras una prueba.","Parta de um fluxo, desenhe telas mínimas, declare ações e documente o que deve mudar após um teste.","Start with a flow, draw minimal screens, state actions, and document what should change after a test."),e("Un botón sin pantalla de éxito no explica qué ocurre después de guardar.","Um botão sem tela de sucesso não explica o que acontece depois de salvar.","A button without a success screen does not explain what happens after saving."),e("Dibujar solo el camino ideal e ignorar errores, cancelación y retorno.","Desenhar apenas o caminho ideal e ignorar erros, cancelamento e retorno.","Drawing only the ideal path and ignoring errors, cancellation, and return."),e("Añade un estado vacío, uno de error y uno de confirmación a tu flujo.","Adicione um estado vazio, um de erro e um de confirmação ao seu fluxo.","Add an empty, error, and confirmation state to your flow."),e("En una revisión temprana, pide feedback sobre secuencia y claridad, no sobre color.","Em uma revisão inicial, peça feedback sobre sequência e clareza, não sobre cor.","In an early review, ask for feedback on sequence and clarity, not color.")),a("w2",e("Anotar para colaborar","Anotar para colaborar","Annotating for collaboration"),e("Las anotaciones vinculan una pantalla con reglas, estados, supuestos y medidas de éxito.","As anotações vinculam uma tela a regras, estados, suposições e medidas de sucesso.","Annotations connect a screen to rules, states, assumptions, and success measures."),e("Una imagen sin intención obliga a otras personas a adivinar comportamientos importantes.","Uma imagem sem intenção obriga outras pessoas a adivinhar comportamentos importantes.","An image without intent makes others guess important behaviors."),e("Etiqueta la acción, condición, feedback, datos requeridos y duda que la prueba debe resolver.","Rotule a ação, condição, feedback, dados necessários e dúvida que o teste deve resolver.","Label the action, condition, feedback, required data, and doubt the test should resolve."),e("'Guardar' puede bloquearse hasta completar campos, informar error o confirmar una actualización.","'Salvar' pode bloquear até completar campos, informar erro ou confirmar uma atualização.","'Save' may be blocked until fields are complete, show an error, or confirm an update."),e("Esconder la lógica porque el wireframe parece autoexplicativo.","Esconder a lógica porque o wireframe parece autoexplicativo.","Hiding logic because the wireframe looks self-explanatory."),e("Anota un formulario con validación, error y comportamiento de reintento.","Anote um formulário com validação, erro e comportamento de nova tentativa.","Annotate a form with validation, error, and retry behavior."),e("Usa anotaciones para alinear investigación, contenido y factibilidad antes de alta fidelidad.","Use anotações para alinhar pesquisa, conteúdo e viabilidade antes da alta fidelidade.","Use annotations to align research, content, and feasibility before high fidelity."))],quiz:i(e("¿Qué debe incluir un flujo low-fi útil?","O que um fluxo low-fi útil deve incluir?","What should a useful low-fi flow include?"),[e("Solo pantallas ideales","Apenas telas ideais","Only ideal screens"),e("Acciones, estados y recuperación de errores relevantes","Ações, estados e recuperação de erros relevantes","Relevant actions, states, and error recovery"),e("Tipografías definitivas","Tipografias definitivas","Final typefaces")],1,e("La baja fidelidad debe revelar comportamientos, no ocultarlos.","A baixa fidelidade deve revelar comportamentos, não ocultá-los.","Low fidelity should reveal behaviors, not hide them."))}),o({id:"ui-design",order:6,level:e("Nivel 6","Nível 6","Level 6"),title:e("UI Design","UI Design","UI Design"),summary:e("Construye interfaces claras mediante jerarquía, tipografía, color, espacio, contenido y estados.","Construa interfaces claras por meio de hierarquia, tipografia, cor, espaço, conteúdo e estados.","Build clear interfaces through hierarchy, typography, color, space, content, and states."),competencies:[e("Aplicar jerarquía visual","Aplicar hierarquia visual","Apply visual hierarchy"),e("Diseñar estados","Desenhar estados","Design states")],caseStudy:e("Civic Desk tiene formularios que se abandonan cuando hay errores. Diseña un sistema de feedback que informe sin culpar.","Civic Desk tem formulários abandonados quando há erros. Desenhe um sistema de feedback que informe sem culpar.","Civic Desk forms are abandoned on error. Design a feedback system that informs without blaming."),guidedPractice:e("Crea tres versiones de una tarjeta, reduce la densidad visual y explica cómo cambia la prioridad.","Crie três versões de um card, reduza a densidade visual e explique como a prioridade muda.","Create three card versions, reduce visual density, and explain how priority changes."),individualPractice:e("Diseña default, hover, focus, pressed, disabled, loading, empty y error para un componente.","Desenhe default, hover, focus, pressed, disabled, loading, empty e error para um componente.","Design default, hover, focus, pressed, disabled, loading, empty, and error for one component."),miniProject:e("Convierte el flujo de Pulse en una interfaz high-fi con decisiones de color, tipo, espacio y contenido documentadas.","Converta o fluxo do Pulse em uma interface high-fi com decisões de cor, tipo, espaço e conteúdo documentadas.","Turn the Pulse flow into a high-fi interface with documented color, type, space, and content decisions."),rubricFocus:[e("Jerarquía","Hierarquia","Hierarchy"),e("Estados y feedback","Estados e feedback","States and feedback")],glossary:[{term:"Estado",definition:e("Condición visual y conductual de un componente ante interacción o datos.","Condição visual e comportamental de um componente diante de interação ou dados.","Visual and behavioral condition of a component in response to interaction or data.")}],lessons:[a("ui1",e("Jerarquía que conduce una tarea","Hierarquia que conduz uma tarefa","Hierarchy that leads a task"),e("La interfaz distribuye atención con tamaño, contraste, proximidad, alineación, espacio y contenido.","A interface distribui atenção com tamanho, contraste, proximidade, alinhamento, espaço e conteúdo.","An interface distributes attention through size, contrast, proximity, alignment, space, and content."),e("La prioridad visual debe corresponder a la prioridad de la tarea, no al interés interno de promoción.","A prioridade visual deve corresponder à prioridade da tarefa, não ao interesse interno de promoção.","Visual priority should correspond to task priority, not an internal promotional interest."),e("Define la acción primaria, crea agrupaciones, reserva contraste para lo importante y comprueba el orden sin leer todo.","Defina a ação principal, crie agrupamentos, reserve contraste para o importante e verifique a ordem sem ler tudo.","Define the primary action, create groupings, reserve contrast for what matters, and check order without reading everything."),e("Una pantalla de reporte necesita primero elegir tipo, luego describir, después adjuntar y finalmente confirmar.","Uma tela de relato precisa primeiro escolher tipo, depois descrever, então anexar e por fim confirmar.","A reporting screen needs type selection first, then description, attachment, and confirmation."),e("Colocar tres llamadas a la acción con el mismo peso visual.","Colocar três chamadas à ação com o mesmo peso visual.","Placing three calls to action with equal visual weight."),e("Haz una prueba de desenfoque: identifica qué entiendes a primera vista y qué compite.","Faça um teste de desfoque: identifique o que entende à primeira vista e o que compete.","Run a blur test: identify what you understand at first glance and what competes."),e("Justifica decisiones visuales con la tarea y la evidencia, no con tendencias.","Justifique decisões visuais com a tarefa e a evidência, não com tendências.","Justify visual decisions with the task and evidence, not trends.")),a("ui2",e("Contenido, feedback y estados","Conteúdo, feedback e estados","Content, feedback, and states"),e("Los textos, cargas, vacíos, éxitos y errores forman parte de la interfaz, no son casos de excepción.","Textos, carregamentos, vazios, sucessos e erros fazem parte da interface, não são casos de exceção.","Text, loading, empty, success, and error states are part of the interface, not exceptions."),e("La gente necesita saber qué pasó, qué puede hacer y qué ocurre después, especialmente cuando algo falla.","As pessoas precisam saber o que aconteceu, o que podem fazer e o que ocorre depois, especialmente quando algo falha.","People need to know what happened, what they can do, and what comes next, especially when something fails."),e("Escribe la causa cuando sea útil, propone una acción de recuperación y conserva la información ya introducida.","Escreva a causa quando for útil, proponha uma ação de recuperação e preserve a informação já inserida.","State the cause when useful, propose recovery, and preserve information already entered."),e("'No pudimos guardar tu reporte. Reintenta; tus fotos siguen adjuntas.' permite continuar sin culpar.","'Não foi possível salvar seu relato. Tente novamente; suas fotos continuam anexadas.' permite continuar sem culpar.","'We could not save your report. Try again; your photos are still attached.' enables recovery without blame."),e("Mostrar 'Error 400' sin explicación, contexto ni siguiente paso.","Mostrar 'Erro 400' sem explicação, contexto ou próximo passo.","Showing 'Error 400' without explanation, context, or next step."),e("Reescribe cinco mensajes de error en tono claro, específico y accionable.","Reescreva cinco mensagens de erro em tom claro, específico e acionável.","Rewrite five error messages in a clear, specific, actionable tone."),e("Incluye estados en la definición de listo y en el handoff técnico.","Inclua estados na definição de pronto e no handoff técnico.","Include states in the definition of done and technical handoff."))],quiz:i(e("¿Cuál es un buen mensaje de error?","Qual é uma boa mensagem de erro?","Which is a good error message?"),[e("Error","Erro","Error"),e("No pudimos guardar. Reintenta; tu trabajo sigue disponible.","Não foi possível salvar. Tente novamente; seu trabalho continua disponível.","We could not save. Try again; your work is still available."),e("Solicitud inválida","Solicitação inválida","Invalid request")],1,e("Un buen feedback explica la situación y ofrece un camino de recuperación.","Um bom feedback explica a situação e oferece um caminho de recuperação.","Good feedback explains the situation and provides a recovery path."))}),o({id:"prototyping",order:7,level:e("Nivel 7","Nível 7","Level 7"),title:e("Prototyping","Prototipagem","Prototyping"),summary:e("Construye representaciones interactivas proporcionales a la pregunta que necesitas responder.","Construa representações interativas proporcionais à pergunta que você precisa responder.","Build interactive representations proportional to the question you need to answer."),competencies:[e("Seleccionar fidelidad","Selecionar fidelidade","Select fidelity"),e("Diseñar interacciones","Desenhar interações","Design interactions")],caseStudy:e("Antes de construir recomendaciones personalizadas para Pulse, decide qué interacción y qué supuesto deben probarse en un prototipo.","Antes de construir recomendações personalizadas para Pulse, decida que interação e qual suposição devem ser testadas em um protótipo.","Before building personalized Pulse recommendations, decide which interaction and assumption to test in a prototype."),guidedPractice:e("Conecta cinco pantallas, agrega un back path y prueba una tarea usando solo una instrucción neutral.","Conecte cinco telas, adicione um caminho de retorno e teste uma tarefa usando apenas uma instrução neutra.","Connect five screens, add a back path, and test a task using one neutral instruction."),individualPractice:e("Crea un prototipo con variable de progreso o estado de confirmación sin duplicar pantallas.","Crie um protótipo com variável de progresso ou estado de confirmação sem duplicar telas.","Create a prototype with a progress variable or confirmation state without duplicating screens."),miniProject:e("Entrega el prototipo de Pulse, un plan de prueba y una lista de supuestos que la interacción no valida.","Entregue o protótipo do Pulse, um plano de teste e uma lista de suposições que a interação não valida.","Deliver the Pulse prototype, a test plan, and a list of assumptions the interaction does not validate."),rubricFocus:[e("Pregunta de aprendizaje","Pergunta de aprendizagem","Learning question"),e("Cobertura de flujo","Cobertura de fluxo","Flow coverage")],glossary:[{term:"Prototipo",definition:e("Representación creada para explorar, comunicar o probar una decisión.","Representação criada para explorar, comunicar ou testar uma decisão.","A representation created to explore, communicate, or test a decision.")}],lessons:[a("p1",e("Prototipar una pregunta","Prototipar uma pergunta","Prototyping a question"),e("Un prototipo no es una versión pequeña del producto; es un instrumento para aprender algo concreto.","Um protótipo não é uma versão pequena do produto; é um instrumento para aprender algo concreto.","A prototype is not a small product version; it is an instrument for learning something specific."),e("La fidelidad equivocada añade coste y puede hacer que el equipo defienda detalles no validados.","A fidelidade errada adiciona custo e pode levar a equipe a defender detalhes não validados.","The wrong fidelity adds cost and can make a team defend unvalidated details."),e("Nombra el supuesto, el comportamiento esperado, la señal y el mínimo artefacto que permite observarla.","Nomeie a suposição, o comportamento esperado, o sinal e o menor artefato que permite observá-la.","Name the assumption, expected behavior, signal, and smallest artifact that allows observation."),e("Para probar si la gente entiende una secuencia, enlaces entre wireframes pueden bastar.","Para testar se as pessoas entendem uma sequência, links entre wireframes podem bastar.","To test whether people understand a sequence, links between wireframes may be enough."),e("Intentar simular datos reales, pagos o automatizaciones antes de validar la tarea.","Tentar simular dados reais, pagamentos ou automações antes de validar a tarefa.","Trying to simulate real data, payments, or automation before validating the task."),e("Escribe una pregunta que tu prototipo sí responde y otra que no puede responder.","Escreva uma pergunta que seu protótipo responde e outra que ele não pode responder.","Write one question your prototype answers and one it cannot answer."),e("Declara límites del prototipo al invitar participantes y stakeholders.","Declare limites do protótipo ao convidar participantes e stakeholders.","State prototype limits when inviting participants and stakeholders.")),a("p2",e("Interacción, variables y recorrido","Interação, variáveis e percurso","Interaction, variables, and journey"),e("La interacción comunica causa y efecto: qué puede hacer una persona, qué cambia y cómo recupera control.","A interação comunica causa e efeito: o que uma pessoa pode fazer, o que muda e como recupera controle.","Interaction communicates cause and effect: what a person can do, what changes, and how control is recovered."),e("Los enlaces que solo avanzan no revelan dudas, reversibilidad ni feedback.","Links que apenas avançam não revelam dúvidas, reversibilidade ou feedback.","Links that only move forward do not reveal uncertainty, reversibility, or feedback."),e("Define trigger, respuesta, transición, estado resultante y rutas de regreso; usa variables cuando el estado cambia.","Defina gatilho, resposta, transição, estado resultante e rotas de retorno; use variáveis quando o estado muda.","Define trigger, response, transition, resulting state, and return routes; use variables when state changes."),e("Completar un hábito puede cambiar una marca, un contador y el mensaje de siguiente acción.","Completar um hábito pode mudar uma marca, um contador e a mensagem de próxima ação.","Completing a habit may change a checkmark, a counter, and the next-action message."),e("Usar animación decorativa como sustituto de una señal de estado.","Usar animação decorativa como substituto de um sinal de estado.","Using decorative animation as a substitute for a state signal."),e("Documenta trigger, resultado y regreso para cuatro interacciones.","Documente gatilho, resultado e retorno para quatro interações.","Document trigger, outcome, and return for four interactions."),e("Revisa que el prototipo permite corregir una decisión sin reiniciar toda la tarea.","Revise se o protótipo permite corrigir uma decisão sem reiniciar toda a tarefa.","Check that the prototype lets a person correct a decision without restarting the task."))],quiz:i(e("¿Qué define primero un prototipo útil?","O que define primeiro um protótipo útil?","What defines a useful prototype first?"),[e("La tendencia visual","A tendência visual","The visual trend"),e("La pregunta de aprendizaje y la señal a observar","A pergunta de aprendizagem e o sinal a observar","The learning question and signal to observe"),e("La cantidad de animaciones","A quantidade de animações","The number of animations")],1,e("La fidelidad y el alcance se derivan de lo que debe aprenderse.","A fidelidade e o escopo derivam do que deve ser aprendido.","Fidelity and scope derive from what must be learned."))}),o({id:"usability-testing",order:8,level:e("Nivel 8","Nível 8","Level 8"),title:e("Usability Testing","Usability Testing","Usability Testing"),summary:e("Observa a personas representativas realizando tareas y convierte evidencia en iteraciones priorizadas.","Observe pessoas representativas realizando tarefas e transforme evidências em iterações priorizadas.","Observe representative people doing tasks and turn evidence into prioritized iterations."),competencies:[e("Moderación neutral","Moderação neutra","Neutral moderation"),e("Priorizar hallazgos","Priorizar achados","Prioritize findings")],caseStudy:e("El prototipo de Pulse tiene una tasa de finalización incierta. Escribe un estudio que diferencie dificultad de tarea y preferencias.","O protótipo do Pulse tem uma taxa de conclusão incerta. Escreva um estudo que diferencie dificuldade de tarefa e preferências.","The Pulse prototype has uncertain completion. Write a study that separates task difficulty from preferences."),guidedPractice:e("Practica una apertura de sesión, una tarea neutral y dos preguntas de seguimiento sin sugerir la respuesta.","Pratique uma abertura de sessão, uma tarefa neutra e duas perguntas de acompanhamento sem sugerir a resposta.","Practice a session opening, one neutral task, and two follow-up questions without suggesting the answer."),individualPractice:e("Observa dos recorridos de prueba y redacta hallazgos que distingan observación, interpretación y recomendación.","Observe dois percursos de teste e redija achados que distingam observação, interpretação e recomendação.","Observe two test runs and write findings that distinguish observation, interpretation, and recommendation."),miniProject:e("Entrega el informe de test de Pulse, severidades, decisiones de iteración y aquello que requiere investigación adicional.","Entregue o relatório de teste do Pulse, severidades, decisões de iteração e o que requer pesquisa adicional.","Deliver the Pulse test report, severities, iteration decisions, and what needs further research."),rubricFocus:[e("Validez de tarea","Validade da tarefa","Task validity"),e("Accionabilidad","Acionabilidade","Actionability")],glossary:[{term:"Severidad",definition:e("Estimación razonada de impacto, frecuencia y persistencia de un problema.","Estimativa fundamentada de impacto, frequência e persistência de um problema.","Reasoned estimate of a problem’s impact, frequency, and persistence.")}],lessons:[a("ut1",e("Tareas que no enseñan la respuesta","Tarefas que não ensinam a resposta","Tasks that do not teach the answer"),e("Una prueba de usabilidad observa cómo alguien persigue un objetivo realista con una interfaz.","Um teste de usabilidade observa como alguém persegue um objetivo realista com uma interface.","A usability test observes how someone pursues a realistic goal with an interface."),e("Una tarea que incluye el nombre del botón mide lectura, no encontrabilidad ni comprensión.","Uma tarefa que inclui o nome do botão mede leitura, não encontrabilidade ou compreensão.","A task that includes a button’s name measures reading, not findability or understanding."),e("Formula contexto y resultado deseado; observa conducta; pregunta después sin defender el diseño.","Formule contexto e resultado desejado; observe comportamento; pergunte depois sem defender o design.","Frame context and desired outcome; observe behavior; ask afterward without defending the design."),e("'Acabas de detectar una fuga. Envía un reporte con foto' es más neutral que 'pulsa Reportar fuga'.","'Você acabou de detectar um vazamento. Envie um relato com foto' é mais neutro que 'clique em Reportar vazamento'.","'You have just spotted a leak. Send a report with a photo' is more neutral than 'click Report leak'."),e("Reformular la tarea cada vez que el participante duda.","Reformular a tarefa toda vez que a pessoa participante hesita.","Rephrasing the task every time a participant hesitates."),e("Transforma tres instrucciones de interfaz en escenarios orientados a objetivo.","Transforme três instruções de interface em cenários orientados a objetivo.","Transform three interface instructions into goal-oriented scenarios."),e("Registra lo que ocurrió antes de decidir por qué ocurrió.","Registre o que ocorreu antes de decidir por que ocorreu.","Record what happened before deciding why it happened.")),a("ut2",e("De observaciones a iteraciones","De observações a iterações","From observations to iterations"),e("Un hallazgo une evidencia, patrón, impacto y recomendación con la confianza adecuada.","Um achado une evidência, padrão, impacto e recomendação com a confiança adequada.","A finding joins evidence, pattern, impact, and recommendation with appropriate confidence."),e("Evita que la lista de problemas se convierta en una colección de opiniones del equipo.","Evita que a lista de problemas se transforme em uma coleção de opiniões da equipe.","It prevents a problem list from becoming a collection of team opinions."),e("Agrupa evidencia, identifica obstáculo, estima impacto, formula cambio y define qué validar después.","Agrupe evidências, identifique obstáculo, estime impacto, formule mudança e defina o que validar depois.","Group evidence, identify obstacle, estimate impact, formulate change, and define what to validate next."),e("Si varias personas no ven el feedback de envío, aumenta visibilidad y vuelve a probar antes de atribuirlo al color.","Se várias pessoas não veem o feedback de envio, aumente a visibilidade e teste novamente antes de atribuí-lo à cor.","If several people miss send feedback, increase visibility and retest before attributing it to color."),e("Etiquetar como crítico todo comentario negativo sin relación con la tarea.","Rotular como crítico todo comentário negativo sem relação com a tarefa.","Labeling every negative comment critical without task connection."),e("Clasifica cinco observaciones en señal aislada, patrón o problema que exige seguimiento.","Classifique cinco observações em sinal isolado, padrão ou problema que exige acompanhamento.","Classify five observations as isolated signal, pattern, or issue needing follow-up."),e("Prioriza por impacto de usuario, riesgo, evidencia y coste de cambio; comunica incertidumbre.","Priorize por impacto no usuário, risco, evidência e custo de mudança; comunique incerteza.","Prioritize by user impact, risk, evidence, and change cost; communicate uncertainty."))],quiz:i(e("¿Qué hace neutral una tarea de prueba?","O que torna uma tarefa de teste neutra?","What makes a test task neutral?"),[e("Nombra el botón que debe pulsarse","Nomeia o botão que deve ser clicado","It names the button to press"),e("Describe un objetivo y contexto, no la ruta","Descreve um objetivo e contexto, não o caminho","It describes a goal and context, not the route"),e("Explica dónde se producirá el error","Explica onde o erro ocorrerá","It explains where the error will occur")],1,e("La tarea debe permitir observar la estrategia natural de la persona.","A tarefa deve permitir observar a estratégia natural da pessoa.","The task should allow observation of the person’s natural strategy."))}),o({id:"responsive-mobile",order:9,level:e("Nivel 9","Nível 9","Level 9"),title:e("Responsive & Mobile UX","Responsive & Mobile UX","Responsive & Mobile UX"),summary:e("Diseña comportamientos adaptables, no solo tamaños reducidos, para móvil, tablet y escritorio.","Desenhe comportamentos adaptáveis, não apenas tamanhos reduzidos, para celular, tablet e desktop.","Design adaptable behaviors, not merely smaller sizes, for mobile, tablet, and desktop."),competencies:[e("Pensar mobile-first","Pensar mobile-first","Think mobile-first"),e("Especificar adaptación","Especificar adaptação","Specify adaptation")],caseStudy:e("Civic Desk necesita mostrar mapa, lista y formulario en pantallas distintas sin ocultar la tarea primaria.","Civic Desk precisa mostrar mapa, lista e formulário em telas diferentes sem ocultar a tarefa principal.","Civic Desk must show map, list, and form across screens without hiding the primary task."),guidedPractice:e("Define el contenido esencial de una tarea móvil antes de expandirla a una columna lateral en escritorio.","Defina o conteúdo essencial de uma tarefa móvel antes de expandi-la para uma coluna lateral no desktop.","Define essential mobile-task content before expanding it to a desktop side panel."),individualPractice:e("Documenta reflujo, prioridad y cambios de navegación en 360, 768 y 1440 píxeles.","Documente refluxo, prioridade e mudanças de navegação em 360, 768 e 1440 pixels.","Document reflow, priority, and navigation changes at 360, 768, and 1440 pixels."),miniProject:e("Entrega la especificación responsive de Civic Desk con imágenes de todos los breakpoints y reglas de comportamiento.","Entregue a especificação responsiva do Civic Desk com imagens de todos os breakpoints e regras de comportamento.","Deliver the Civic Desk responsive specification with all breakpoint visuals and behavior rules."),rubricFocus:[e("Prioridad contextual","Prioridade contextual","Contextual priority"),e("Continuidad de tarea","Continuidade da tarefa","Task continuity")],glossary:[{term:"Mobile-first",definition:e("Estrategia que prioriza las restricciones y tareas esenciales del contexto móvil antes de ampliar.","Estratégia que prioriza as restrições e tarefas essenciais do contexto móvel antes de ampliar.","Strategy that prioritizes constraints and essential mobile-context tasks before expanding.")}],lessons:[a("rm1",e("Diseñar comportamiento, no encoger","Desenhar comportamento, não encolher","Design behavior, not shrinkage"),e("Responsive design redefine orden, densidad, navegación e interacción según espacio, entrada y contexto.","Responsive design redefine ordem, densidade, navegação e interação conforme espaço, entrada e contexto.","Responsive design redefines order, density, navigation, and interaction by space, input, and context."),e("Reducir una pantalla de escritorio suele dejar controles pequeños, contenido secundario dominante y rutas largas.","Reduzir uma tela desktop costuma deixar controles pequenos, conteúdo secundário dominante e caminhos longos.","Shrinking a desktop screen often leaves small controls, dominant secondary content, and long paths."),e("Empieza por la tarea móvil, define contenido indispensable y declara qué aparece, se reordena, colapsa o cambia de control.","Comece pela tarefa móvel, defina conteúdo indispensável e declare o que aparece, se reordena, colapsa ou muda de controle.","Start with the mobile task, define indispensable content, and state what appears, reorders, collapses, or changes control."),e("Un mapa puede pasar de panel persistente a vista invocable para preservar el formulario en móvil.","Um mapa pode passar de painel persistente a visualização invocável para preservar o formulário no celular.","A map can move from persistent panel to summonable view to preserve the mobile form."),e("Definir breakpoints solo por dispositivos comerciales sin observar cambios reales de contenido.","Definir breakpoints apenas por dispositivos comerciais sem observar mudanças reais de conteúdo.","Defining breakpoints only by commercial devices without observing real content changes."),e("Escribe reglas de cambio para una tabla, un formulario y una navegación.","Escreva regras de mudança para uma tabela, um formulário e uma navegação.","Write change rules for a table, form, and navigation."),e("Incluye comportamiento responsive en el handoff, no únicamente capturas de tres pantallas.","Inclua comportamento responsivo no handoff, não apenas capturas de três telas.","Include responsive behavior in handoff, not only screenshots of three screens.")),a("rm2",e("Tacto, alcance y continuidad","Toque, alcance e continuidade","Touch, reach, and continuity"),e("Los contextos móviles cambian atención, alcance del pulgar, conectividad y tolerancia a interrupciones.","Os contextos móveis mudam atenção, alcance do polegar, conectividade e tolerância a interrupções.","Mobile contexts change attention, thumb reach, connectivity, and interruption tolerance."),e("La tarea debe resistir pausas, teclado virtual, errores de red y retorno sin pérdida de información.","A tarefa deve resistir a pausas, teclado virtual, erros de rede e retorno sem perda de informação.","The task must withstand pauses, virtual keyboards, network errors, and return without losing information."),e("Asegura objetivos táctiles claros, conserva borradores, evita acciones destructivas cercanas y prueba con teclado abierto.","Garanta alvos de toque claros, preserve rascunhos, evite ações destrutivas próximas e teste com teclado aberto.","Ensure clear touch targets, preserve drafts, avoid adjacent destructive actions, and test with the keyboard open."),e("Al adjuntar una foto, conservar texto y ubicación protege la tarea si la persona cambia de aplicación.","Ao anexar uma foto, preservar texto e localização protege a tarefa se a pessoa mudar de aplicativo.","When attaching a photo, preserving text and location protects the task if the person switches apps."),e("Confiar en hover para explicar o descubrir una acción móvil.","Confiar em hover para explicar ou descobrir uma ação móvel.","Relying on hover to explain or reveal a mobile action."),e("Audita una tarea con una mano, conexión inestable y teclado visible.","Audite uma tarefa com uma mão, conexão instável e teclado visível.","Audit a task one-handed, on unstable connection, and with keyboard visible."),e("Negocia con ingeniería estados de borrador, reintento y pérdida de conectividad.","Negocie com engenharia estados de rascunho, nova tentativa e perda de conectividade.","Negotiate draft, retry, and connectivity-loss states with engineering."))],quiz:i(e("¿Qué cambia en un diseño responsive serio?","O que muda em um design responsivo sério?","What changes in serious responsive design?"),[e("Solo el ancho","Apenas a largura","Only width"),e("Orden, prioridad, interacción y densidad según contexto","Ordem, prioridade, interação e densidade conforme o contexto","Order, priority, interaction, and density by context"),e("Solo el tamaño de fuente","Apenas o tamanho da fonte","Only font size")],1,e("La adaptación preserva la tarea con distintas restricciones.","A adaptação preserva a tarefa sob restrições diferentes.","Adaptation preserves the task under different constraints."))}),o({id:"accessibility",order:10,level:e("Nivel 10","Nível 10","Level 10"),title:e("Accessibility","Acessibilidade","Accessibility"),summary:e("Integra accesibilidad e inclusión desde la definición hasta la evaluación de la experiencia.","Integre acessibilidade e inclusão desde a definição até a avaliação da experiência.","Integrate accessibility and inclusion from experience definition through evaluation."),competencies:[e("Aplicar WCAG","Aplicar WCAG","Apply WCAG"),e("Diseñar alternativas","Desenhar alternativas","Design alternatives")],caseStudy:e("Una solicitud de Civic Desk requiere mapa, foto y formulario. Identifica barreras para teclado, lector de pantalla, contraste y carga cognitiva.","Uma solicitação do Civic Desk requer mapa, foto e formulário. Identifique barreiras para teclado, leitor de tela, contraste e carga cognitiva.","A Civic Desk report requires map, photo, and form. Identify barriers for keyboard, screen reader, contrast, and cognitive load."),guidedPractice:e("Revisa una pantalla con orden de foco, etiquetas, contraste, tamaño táctil y mensajes no dependientes del color.","Revise uma tela com ordem de foco, rótulos, contraste, tamanho de toque e mensagens não dependentes de cor.","Review a screen for focus order, labels, contrast, touch size, and messages not dependent on color."),individualPractice:e("Diseña una alternativa accesible para un gráfico de progreso y valida su comprensión sin visión de color.","Desenhe uma alternativa acessível para um gráfico de progresso e valide sua compreensão sem visão de cor.","Design an accessible alternative for a progress chart and validate understanding without color vision."),miniProject:e("Entrega una auditoría de accesibilidad de Civic Desk con barreras, criterio, severidad, solución y prueba posterior.","Entregue uma auditoria de acessibilidade do Civic Desk com barreiras, critério, severidade, solução e teste posterior.","Deliver a Civic Desk accessibility audit with barriers, criterion, severity, solution, and retest."),rubricFocus:[e("Perceptible y operable","Perceptível e operável","Perceivable and operable"),e("Inclusión cognitiva","Inclusão cognitiva","Cognitive inclusion")],glossary:[{term:"WCAG",definition:e("Pautas de accesibilidad web organizadas en principios y criterios de éxito comprobables.","Diretrizes de acessibilidade web organizadas em princípios e critérios de sucesso verificáveis.","Web accessibility guidelines organized as principles and testable success criteria.")}],lessons:[a("a1",e("Diseñar para más de una forma de usar","Desenhar para mais de uma forma de usar","Designing for more than one way of use"),e("La accesibilidad busca que la información y funcionalidad sean perceptibles, operables, comprensibles y robustas.","A acessibilidade busca tornar informação e funcionalidade perceptíveis, operáveis, compreensíveis e robustas.","Accessibility aims for information and functionality to be perceivable, operable, understandable, and robust."),e("No es una comprobación final: las decisiones tempranas sobre estructura, contenido y foco determinan barreras posteriores.","Não é uma verificação final: decisões iniciais sobre estrutura, conteúdo e foco determinam barreiras posteriores.","It is not a final check: early structure, content, and focus decisions determine later barriers."),e("Define necesidades diversas, diseña alternativas, usa semántica y evalúa con teclado, tecnologías de asistencia y personas cuando sea posible.","Defina necessidades diversas, desenhe alternativas, use semântica e avalie com teclado, tecnologias assistivas e pessoas quando possível.","Define diverse needs, design alternatives, use semantics, and evaluate with keyboard, assistive tech, and people when possible."),e("Un icono de estado necesita texto, forma o posición adicional para no depender del color.","Um ícone de estado precisa de texto, forma ou posição adicional para não depender da cor.","A status icon needs text, shape, or position in addition so it does not rely on color."),e("Asumir que una herramienta automática certifica por sí sola una experiencia accesible.","Supor que uma ferramenta automática certifica sozinha uma experiência acessível.","Assuming an automated tool alone certifies an accessible experience."),e("Audita una interacción únicamente con teclado y registra cada punto de bloqueo.","Audite uma interação apenas com teclado e registre cada ponto de bloqueio.","Audit an interaction using only a keyboard and record every blockage."),e("Incorpora criterios de accesibilidad en la definición de éxito de cada proyecto.","Incorpore critérios de acessibilidade na definição de sucesso de cada projeto.","Incorporate accessibility criteria into every project’s success definition.")),a("a2",e("Foco, contenido y carga cognitiva","Foco, conteúdo e carga cognitiva","Focus, content, and cognitive load"),e("El orden de foco, etiquetas explícitas, instrucciones claras y recuperación de errores sostienen la autonomía.","A ordem de foco, rótulos explícitos, instruções claras e recuperação de erros sustentam a autonomia.","Focus order, explicit labels, clear instructions, and error recovery sustain autonomy."),e("Una interfaz puede tener contraste correcto y seguir siendo inaccesible si el foco salta, se pierde o no comunica contexto.","Uma interface pode ter contraste correto e ainda ser inacessível se o foco salta, se perde ou não comunica contexto.","An interface can have correct contrast and still be inaccessible if focus jumps, disappears, or fails to communicate context."),e("Diseña secuencia lógica, foco visible, labels persistentes, instrucciones cercanas y feedback que no dependa de memoria.","Desenhe sequência lógica, foco visível, labels persistentes, instruções próximas e feedback que não dependa de memória.","Design logical sequence, visible focus, persistent labels, proximate instructions, and feedback not dependent on memory."),e("Tras enviar un formulario, mover foco al resumen de resultado informa qué cambió y qué corregir.","Após enviar um formulário, mover o foco ao resumo do resultado informa o que mudou e o que corrigir.","After submitting a form, moving focus to the result summary explains what changed and what to fix."),e("Usar placeholder como única etiqueta de un campo.","Usar placeholder como único rótulo de um campo.","Using placeholder as a field’s only label."),e("Rediseña un formulario con labels, ayuda contextual, foco y resumen de errores.","Redesenhe um formulário com labels, ajuda contextual, foco e resumo de erros.","Redesign a form with labels, contextual help, focus, and error summary."),e("Incluye casos de uso de asistencia en entrevistas, prototipos y pruebas de aceptación.","Inclua casos de uso de assistência em entrevistas, protótipos e testes de aceitação.","Include assistive-use cases in interviews, prototypes, and acceptance tests."))],quiz:i(e("¿Qué práctica evita depender solo del color?","Que prática evita depender apenas da cor?","Which practice avoids relying only on color?"),[e("Aumentar la saturación","Aumentar a saturação","Increasing saturation"),e("Combinar color con texto, forma o posición","Combinar cor com texto, forma ou posição","Combining color with text, shape, or position"),e("Ocultar los errores","Ocultar os erros","Hiding errors")],1,e("La información crítica necesita canales redundantes y perceptibles.","Informação crítica precisa de canais redundantes e perceptíveis.","Critical information needs redundant, perceivable channels."))}),o({id:"design-systems",order:11,level:e("Nivel 11","Nível 11","Level 11"),title:e("Design Systems","Design Systems","Design Systems"),summary:e("Crea foundations, tokens, componentes y gobierno para mantener coherencia sin frenar la evolución.","Crie foundations, tokens, componentes e governança para manter coerência sem frear a evolução.","Create foundations, tokens, components, and governance to maintain consistency without blocking evolution."),competencies:[e("Definir tokens","Definir tokens","Define tokens"),e("Documentar componentes","Documentar componentes","Document components")],caseStudy:e("Field Notes crece con equipos distintos. Decide qué debe ser foundation, componente, patrón o decisión local.","Field Notes cresce com equipes diferentes. Decida o que deve ser foundation, componente, padrão ou decisão local.","Field Notes is growing across teams. Decide what should be a foundation, component, pattern, or local decision."),guidedPractice:e("Convierte tres botones duplicados en un componente con propiedades de intención, tamaño, estado e icono.","Converta três botões duplicados em um componente com propriedades de intenção, tamanho, estado e ícone.","Turn three duplicate buttons into a component with intent, size, state, and icon properties."),individualPractice:e("Crea tokens primitivos y semánticos para color, espacio, tipo y elevación; prueba modo claro y oscuro.","Crie tokens primitivos e semânticos para cor, espaço, tipo e elevação; teste modo claro e escuro.","Create primitive and semantic tokens for color, space, type, and elevation; test light and dark modes."),miniProject:e("Entrega la biblioteca de Field Notes: foundations, componentes, variantes, estados, documentación y regla de contribución.","Entregue a biblioteca do Field Notes: foundations, componentes, variantes, estados, documentação e regra de contribuição.","Deliver the Field Notes library: foundations, components, variants, states, documentation, and contribution rule."),rubricFocus:[e("Escalabilidad","Escalabilidade","Scalability"),e("Gobernanza","Governança","Governance")],glossary:[{term:"Token",definition:e("Valor reutilizable que representa una decisión de diseño y puede cambiar por contexto.","Valor reutilizável que representa uma decisão de design e pode mudar por contexto.","Reusable value representing a design decision that can change by context.")}],lessons:[a("ds1",e("De decisiones a tokens","De decisões a tokens","From decisions to tokens"),e("Los tokens capturan decisiones repetibles de color, tipografía, espacio, forma y movimiento en valores reutilizables.","Tokens capturam decisões repetíveis de cor, tipografia, espaço, forma e movimento em valores reutilizáveis.","Tokens capture repeatable decisions about color, type, space, shape, and motion as reusable values."),e("Separar valor primitivo y propósito semántico permite cambiar un tema sin buscar valores en cada componente.","Separar valor primitivo e propósito semântico permite mudar um tema sem procurar valores em cada componente.","Separating primitive value and semantic purpose allows theme change without hunting values in every component."),e("Define foundations, crea alias semánticos, nombra por propósito y prueba modos o contextos diferentes.","Defina foundations, crie aliases semânticos, nomeie por propósito e teste modos ou contextos diferentes.","Define foundations, create semantic aliases, name by purpose, and test different modes or contexts."),e("`color.text.danger` comunica uso mejor que un hexadecimal repetido en alertas y validaciones.","`color.text.danger` comunica uso melhor que um hexadecimal repetido em alertas e validações.","`color.text.danger` communicates purpose better than a repeated hexadecimal in alerts and validation."),e("Nombrar tokens por color visual cuando su significado cambia entre contextos.","Nomear tokens pela cor visual quando seu significado muda entre contextos.","Naming tokens by visual color when their meaning changes across contexts."),e("Propón una jerarquía de tokens para un estado de error en dos temas.","Proponha uma hierarquia de tokens para um estado de erro em dois temas.","Propose a token hierarchy for an error state in two themes."),e("Alinea tokens de diseño y código antes de escalar una biblioteca.","Alinhe tokens de design e código antes de escalar uma biblioteca.","Align design and code tokens before scaling a library.")),a("ds2",e("Componentes, variantes y gobierno","Componentes, variantes e governança","Components, variants, and governance"),e("Un componente encapsula anatomía, comportamiento, estados, accesibilidad y reglas de uso; no es solo un rectángulo reutilizable.","Um componente encapsula anatomia, comportamento, estados, acessibilidade e regras de uso; não é apenas um retângulo reutilizável.","A component encapsulates anatomy, behavior, states, accessibility, and usage rules; it is not merely a reusable rectangle."),e("Las variantes reducen duplicación solo cuando describen cambios coherentes y no colecciones sin límite.","Variantes reduzem duplicação apenas quando descrevem mudanças coerentes e não coleções sem limite.","Variants reduce duplication only when they describe coherent changes, not unbounded collections."),e("Define propósito, anatomía, propiedades, estados, contenido permitido, accesibilidad, ejemplos y mantenimiento.","Defina propósito, anatomia, propriedades, estados, conteúdo permitido, acessibilidade, exemplos e manutenção.","Define purpose, anatomy, properties, states, permitted content, accessibility, examples, and maintenance."),e("Un botón tiene intención, tamaño y carga; una tarjeta puede requerir composición distinta y no debe ser una variante del botón.","Um botão tem intenção, tamanho e carregamento; um card pode exigir composição diferente e não deve ser variante do botão.","A button has intent, size, and loading; a card may need different composition and should not be a button variant."),e("Publicar componentes sin guía de cuándo usarlos, cambiarlos o retirarlos.","Publicar componentes sem guia de quando usá-los, mudá-los ou retirá-los.","Publishing components without guidance on when to use, change, or retire them."),e("Documenta un componente de formulario con anatomía, estados y criterios de accesibilidad.","Documente um componente de formulário com anatomia, estados e critérios de acessibilidade.","Document a form component with anatomy, states, and accessibility criteria."),e("Establece una propuesta de contribución que proteja coherencia y permita aprendizaje de equipos.","Estabeleça uma proposta de contribuição que proteja coerência e permita aprendizado das equipes.","Set a contribution proposal that protects consistency and enables team learning."))],quiz:i(e("¿Por qué usar tokens semánticos?","Por que usar tokens semânticos?","Why use semantic tokens?"),[e("Para repetir hexadecimales","Para repetir hexadecimais","To repeat hexadecimals"),e("Para expresar propósito y cambiar contexto sin editar cada componente","Para expressar propósito e mudar contexto sem editar cada componente","To express purpose and change context without editing every component"),e("Para evitar documentación","Para evitar documentação","To avoid documentation")],1,e("Los nombres semánticos desacoplan intención y valor concreto.","Nomes semânticos desacoplam intenção e valor concreto.","Semantic names decouple intent from a concrete value."))}),o({id:"advanced-ux",order:12,level:e("Nivel 12","Nível 12","Level 12"),title:e("Advanced UX","Advanced UX","Advanced UX"),summary:e("Aborda servicios, sistemas, contenido, ética y trade-offs donde no existe una solución única.","Aborde serviços, sistemas, conteúdo, ética e trade-offs nos quais não existe uma solução única.","Address services, systems, content, ethics, and trade-offs where no single solution exists."),competencies:[e("Mapear sistemas","Mapear sistemas","Map systems"),e("Explicitar trade-offs","Explicitar trade-offs","Make trade-offs explicit")],caseStudy:e("Un sistema de citas coordina personas, notificaciones, capacidad clínica y normas. Mapea impactos más allá de la pantalla.","Um sistema de consultas coordena pessoas, notificações, capacidade clínica e normas. Mapeie impactos além da tela.","An appointment system coordinates people, notifications, clinical capacity, and rules. Map impacts beyond the screen."),guidedPractice:e("Construye un service blueprint con frontstage, backstage, dependencias y puntos de fallo para una cita.","Construa um service blueprint com frontstage, backstage, dependências e pontos de falha para uma consulta.","Build a service blueprint with frontstage, backstage, dependencies, and failure points for an appointment."),individualPractice:e("Evalúa una decisión de personalización por beneficio, daño potencial, consentimiento, reversibilidad y exclusión.","Avalie uma decisão de personalização por benefício, dano potencial, consentimento, reversibilidade e exclusão.","Evaluate a personalization decision by benefit, potential harm, consent, reversibility, and exclusion."),miniProject:e("Entrega un blueprint de servicio y una decisión de diseño con alternativas, riesgos y plan de validación.","Entregue um blueprint de serviço e uma decisão de design com alternativas, riscos e plano de validação.","Deliver a service blueprint and design decision with alternatives, risks, and validation plan."),rubricFocus:[e("Pensamiento sistémico","Pensamento sistêmico","Systems thinking"),e("Ética aplicada","Ética aplicada","Applied ethics")],glossary:[{term:"Service blueprint",definition:e("Mapa que relaciona experiencia visible, procesos internos, personas y dependencias.","Mapa que relaciona experiência visível, processos internos, pessoas e dependências.","Map relating visible experience, internal processes, people, and dependencies.")}],lessons:[a("ax1",e("La experiencia vive en un sistema","A experiência vive em um sistema","Experience lives in a system"),e("Una interfaz es la parte visible de un servicio que depende de personas, reglas, operaciones, datos y tiempos.","Uma interface é a parte visível de um serviço que depende de pessoas, regras, operações, dados e tempos.","An interface is the visible part of a service that depends on people, rules, operations, data, and time."),e("Optimizar una pantalla sin ver dependencias puede desplazar una carga o crear un nuevo punto de fallo.","Otimizar uma tela sem ver dependências pode deslocar uma carga ou criar um novo ponto de falha.","Optimizing a screen without seeing dependencies can shift burden or create a new failure point."),e("Mapea actor, evidencia visible, proceso interno, política, sistema y escenario de fallo antes de intervenir.","Mapeie ator, evidência visível, processo interno, política, sistema e cenário de falha antes de intervir.","Map actor, visible evidence, internal process, policy, system, and failure scenario before intervening."),e("Confirmar una cita puede requerir disponibilidad, autorización y un mensaje comprensible, no solo un botón.","Confirmar uma consulta pode exigir disponibilidade, autorização e uma mensagem compreensível, não apenas um botão.","Confirming an appointment may require availability, authorization, and an understandable message, not only a button."),e("Atribuir todos los problemas de servicio a la interfaz.","Atribuir todos os problemas de serviço à interface.","Attributing every service problem to the interface."),e("Identifica tres dependencias invisibles detrás de una acción digital.","Identifique três dependências invisíveis por trás de uma ação digital.","Identify three invisible dependencies behind a digital action."),e("Presenta impactos de diseño en un blueprint para negociar cambios interdisciplinares.","Apresente impactos de design em um blueprint para negociar mudanças interdisciplinares.","Present design impacts in a blueprint to negotiate cross-disciplinary change.")),a("ax2",e("Trade-offs y diseño responsable","Trade-offs e design responsável","Trade-offs and responsible design"),e("Las decisiones avanzadas comparan beneficios y costes distribuidos de manera desigual entre personas y contextos.","Decisões avançadas comparam benefícios e custos distribuídos de forma desigual entre pessoas e contextos.","Advanced decisions compare benefits and costs distributed unequally across people and contexts."),e("Explicitar riesgos permite evitar que eficiencia para un grupo se convierta en exclusión o daño para otro.","Explicitar riscos permite evitar que eficiência para um grupo se transforme em exclusão ou dano para outro.","Making risks explicit helps prevent efficiency for one group becoming exclusion or harm for another."),e("Enumera afectados, beneficios, daños, incertidumbres, salvaguardas, reversibilidad y evidencia requerida.","Liste afetados, benefícios, danos, incertezas, salvaguardas, reversibilidade e evidência necessária.","List affected people, benefits, harms, uncertainties, safeguards, reversibility, and required evidence."),e("Una notificación insistente puede mejorar asistencia y a la vez afectar a alguien que comparte dispositivo.","Uma notificação insistente pode melhorar comparecimento e ao mesmo tempo afetar alguém que compartilha dispositivo.","An insistent notification may improve attendance and also affect someone sharing a device."),e("Presentar una decisión ética como una casilla de cumplimiento sin contexto.","Apresentar uma decisão ética como uma caixa de conformidade sem contexto.","Presenting an ethical decision as a compliance checkbox without context."),e("Escribe un registro de trade-off para una función de recordatorios.","Escreva um registro de trade-off para uma função de lembretes.","Write a trade-off record for a reminder feature."),e("Eleva riesgos temprano y propone experimentos reversibles antes de escalar una decisión.","Eleve riscos cedo e proponha experimentos reversíveis antes de escalar uma decisão.","Raise risks early and propose reversible experiments before scaling a decision."))],quiz:i(e("¿Qué añade un service blueprint a un journey?","O que um service blueprint adiciona a uma jornada?","What does a service blueprint add to a journey?"),[e("Solo más colores","Apenas mais cores","Only more colors"),e("Procesos internos, dependencias y puntos de fallo","Processos internos, dependências e pontos de falha","Internal processes, dependencies, and failure points"),e("Una interfaz terminada","Uma interface finalizada","A finished interface")],1,e("El blueprint conecta la experiencia visible con el sistema que la posibilita.","O blueprint conecta a experiência visível ao sistema que a possibilita.","A blueprint connects visible experience with the system enabling it."))}),o({id:"product-design",order:13,level:e("Nivel 13","Nível 13","Level 13"),title:e("Product Design","Product Design","Product Design"),summary:e("Equilibra necesidades de usuarios, negocio y tecnología mediante outcomes, experimentos y decisiones priorizadas.","Equilibre necessidades de usuários, negócio e tecnologia por meio de outcomes, experimentos e decisões priorizadas.","Balance user, business, and technology needs through outcomes, experiments, and prioritized decisions."),competencies:[e("Definir outcomes","Definir outcomes","Define outcomes"),e("Priorizar experimentos","Priorizar experimentos","Prioritize experiments")],caseStudy:e("Una plataforma educativa tiene baja activación. Evita saltar a una nueva función y define el outcome, oportunidad y primera hipótesis.","Uma plataforma educacional tem baixa ativação. Evite pular para uma nova função e defina outcome, oportunidade e primeira hipótese.","A learning platform has low activation. Avoid jumping to a feature and define outcome, opportunity, and first hypothesis."),guidedPractice:e("Separa métricas de actividad, producto y resultado; identifica cuál representa cambio de comportamiento útil.","Separe métricas de atividade, produto e resultado; identifique qual representa mudança de comportamento útil.","Separate activity, product, and outcome metrics; identify which represents useful behavior change."),individualPractice:e("Prioriza cuatro oportunidades por impacto, evidencia, coste y riesgo; explica lo que no harás todavía.","Priorize quatro oportunidades por impacto, evidência, custo e risco; explique o que ainda não fará.","Prioritize four opportunities by impact, evidence, cost, and risk; explain what you will not do yet."),miniProject:e("Entrega un product brief para activación: outcome, usuarios, oportunidad, hipótesis, experimento, métrica y guardrail.","Entregue um product brief para ativação: outcome, usuários, oportunidade, hipótese, experimento, métrica e guardrail.","Deliver an activation product brief: outcome, users, opportunity, hypothesis, experiment, metric, and guardrail."),rubricFocus:[e("Orientación a outcome","Orientação a outcome","Outcome orientation"),e("Rigor de hipótesis","Rigor de hipótese","Hypothesis rigor")],glossary:[{term:"Outcome",definition:e("Cambio observable y valioso en comportamiento o condición, no una lista de entregables.","Mudança observável e valiosa em comportamento ou condição, não uma lista de entregáveis.","Observable, valuable change in behavior or condition, not a deliverable list.")}],lessons:[a("pd1",e("De output a outcome","De output a outcome","From output to outcome"),e("Un output es algo entregado; un outcome es un cambio que la entrega busca producir y que debe poder observarse.","Um output é algo entregue; um outcome é uma mudança que a entrega busca produzir e que deve poder ser observada.","An output is something delivered; an outcome is a change the delivery seeks to produce and should be observable."),e("Distinguirlos permite cuestionar una función cuando no contribuye a una meta valiosa.","Distingui-los permite questionar uma função quando não contribui para uma meta valiosa.","Distinguishing them lets teams question a feature when it does not contribute to a valuable goal."),e("Declara audiencia, comportamiento actual, cambio deseado, medida, horizonte y guardrails de daño o calidad.","Declare público, comportamento atual, mudança desejada, medida, horizonte e guardrails de dano ou qualidade.","State audience, current behavior, desired change, measure, horizon, and harm or quality guardrails."),e("'Lanzar onboarding' es output; 'más personas completan una primera tarea relevante' es outcome.","'Lançar onboarding' é output; 'mais pessoas completam uma primeira tarefa relevante' é outcome.","'Launch onboarding' is an output; 'more people complete a meaningful first task' is an outcome."),e("Usar una métrica fácil de subir aunque empeore la experiencia o excluya usuarios.","Usar uma métrica fácil de subir mesmo que piore a experiência ou exclua usuários.","Using a metric that is easy to raise even if it worsens experience or excludes users."),e("Reformula tres entregables como outcomes con guardrails.","Reformule três entregáveis como outcomes com guardrails.","Reframe three deliverables as outcomes with guardrails."),e("Alinea decisiones de diseño con una métrica y evidencia cualitativa complementaria.","Alinhe decisões de design com uma métrica e evidência qualitativa complementar.","Align design decisions with a metric and complementary qualitative evidence.")),a("pd2",e("Hipótesis y experimentos responsables","Hipóteses e experimentos responsáveis","Responsible hypotheses and experiments"),e("Una hipótesis declara para quién, qué cambio se espera, por qué y qué señal indicaría que no funcionó.","Uma hipótese declara para quem, qual mudança se espera, por quê e qual sinal indicaria que não funcionou.","A hypothesis states for whom, what change is expected, why, and what signal would show it did not work."),e("Hace visible qué está por aprender antes de comprometer un roadmap o construir a escala.","Torna visível o que ainda precisa ser aprendido antes de comprometer um roadmap ou construir em escala.","It makes visible what needs learning before committing a roadmap or building at scale."),e("Prioriza el supuesto más riesgoso, elige un experimento ético y proporcional, define éxito y decide de antemano qué harás con cada resultado.","Priorize a suposição mais arriscada, escolha um experimento ético e proporcional, defina sucesso e decida antes o que fará com cada resultado.","Prioritize the riskiest assumption, choose an ethical proportional experiment, define success, and decide in advance what you will do with each result."),e("Un prototipo puede evaluar comprensión antes de cambiar el flujo de miles de estudiantes.","Um protótipo pode avaliar compreensão antes de mudar o fluxo de milhares de estudantes.","A prototype can evaluate comprehension before changing a flow for thousands of learners."),e("Llamar experimento a lanzar una función sin grupo, señal ni criterio de decisión.","Chamar de experimento lançar uma função sem grupo, sinal ou critério de decisão.","Calling a feature launch an experiment without group, signal, or decision criterion."),e("Escribe una hipótesis falsable y un experimento que reduzca riesgo sin recolectar datos innecesarios.","Escreva uma hipótese falsificável e um experimento que reduza risco sem coletar dados desnecessários.","Write a falsifiable hypothesis and experiment that reduces risk without collecting unnecessary data."),e("Comparte resultados, incluidos los negativos, para proteger aprendizaje y evitar repetir costes.","Compartilhe resultados, inclusive negativos, para proteger aprendizagem e evitar repetir custos.","Share results, including negative ones, to protect learning and avoid repeated cost."))],quiz:i(e("¿Cuál es un outcome?","Qual é um outcome?","Which is an outcome?"),[e("Publicar un rediseño","Publicar um redesign","Publish a redesign"),e("Aumentar la finalización de una primera tarea relevante sin elevar errores","Aumentar a conclusão de uma primeira tarefa relevante sem elevar erros","Increase completion of a meaningful first task without raising errors"),e("Crear diez pantallas","Criar dez telas","Create ten screens")],1,e("Un outcome describe cambio de comportamiento y guardrail, no volumen de producción.","Um outcome descreve mudança de comportamento e guardrail, não volume de produção.","An outcome describes behavioral change and guardrail, not production volume."))}),o({id:"ux-ai",order:14,level:e("Nivel 14","Nível 14","Level 14"),title:e("UX + AI","UX + IA","UX + AI"),summary:e("Utiliza IA como apoyo para ampliar pensamiento, nunca como sustituto de evidencia, criterio o responsabilidad.","Use IA como apoio para ampliar o pensamento, nunca como substituto de evidência, critério ou responsabilidade.","Use AI as support to expand thinking, never as a substitute for evidence, judgment, or responsibility."),competencies:[e("Diseñar con supervisión","Desenhar com supervisão","Design with oversight"),e("Proteger datos","Proteger dados","Protect data")],caseStudy:e("Un equipo quiere usar IA para sintetizar entrevistas. Define qué datos son aceptables, qué debe verificar una persona y cómo se conserva trazabilidad.","Uma equipe quer usar IA para sintetizar entrevistas. Defina quais dados são aceitáveis, o que uma pessoa deve verificar e como preservar rastreabilidade.","A team wants AI to synthesize interviews. Define acceptable data, what a person must verify, and how traceability is preserved."),guidedPractice:e("Compara una síntesis asistida con las notas de fuente, marca afirmaciones no respaldadas y reescribe el hallazgo.","Compare uma síntese assistida com as notas de fonte, marque afirmações não respaldadas e reescreva o achado.","Compare an assisted synthesis with source notes, mark unsupported claims, and rewrite the finding."),individualPractice:e("Diseña un prompt para generar alternativas de microcopy con contexto, restricciones de tono, criterios de inclusión y revisión humana.","Desenhe um prompt para gerar alternativas de microcopy com contexto, restrições de tom, critérios de inclusão e revisão humana.","Design a prompt to generate microcopy alternatives with context, tone constraints, inclusion criteria, and human review."),miniProject:e("Entrega un protocolo de uso responsable de IA para research, ideación y writing con límites, revisión y registro de decisiones.","Entregue um protocolo de uso responsável de IA para research, ideação e writing com limites, revisão e registro de decisões.","Deliver a responsible-AI protocol for research, ideation, and writing with boundaries, review, and decision records."),rubricFocus:[e("Validación humana","Validação humana","Human validation"),e("Privacidad y sesgo","Privacidade e viés","Privacy and bias")],glossary:[{term:"Alucinación",definition:e("Afirmación generada que parece plausible pero no está respaldada por la evidencia proporcionada.","Afirmação gerada que parece plausível, mas não é respaldada pela evidência fornecida.","Generated claim that seems plausible but is not supported by provided evidence.")}],lessons:[a("ai1",e("IA para ampliar, no para sustituir","IA para ampliar, não para substituir","AI to expand, not replace"),e("La IA puede proponer, resumir, variar y clasificar, pero no conoce por sí misma el contexto, las personas ni la verdad de una investigación.","A IA pode propor, resumir, variar e classificar, mas não conhece por si só o contexto, as pessoas ou a verdade de uma pesquisa.","AI can propose, summarize, vary, and classify, but does not itself know context, people, or research truth."),e("La velocidad sin verificación amplifica sesgos, errores y decisiones que nadie puede explicar.","A velocidade sem verificação amplifica vieses, erros e decisões que ninguém consegue explicar.","Speed without verification amplifies bias, errors, and decisions no one can explain."),e("Define tarea apta, minimiza datos, da contexto, pide estructura, contrasta con fuentes y documenta revisión humana.","Defina tarefa adequada, minimize dados, dê contexto, peça estrutura, contraste com fontes e documente revisão humana.","Define a suitable task, minimize data, provide context, request structure, compare with sources, and document human review."),e("Una IA puede sugerir temas en notas anonimizadas; el equipo verifica cada tema contra citas y decide qué importa.","Uma IA pode sugerir temas em notas anonimizadas; a equipe verifica cada tema contra citações e decide o que importa.","AI can suggest themes in anonymized notes; the team checks each theme against quotes and decides what matters."),e("Pegar transcripciones identificables o aceptar un resumen sin trazabilidad.","Colar transcrições identificáveis ou aceitar um resumo sem rastreabilidade.","Pasting identifiable transcripts or accepting a summary without traceability."),e("Crea una matriz de tarea, riesgo, datos permitidos, revisión y evidencia de respaldo.","Crie uma matriz de tarefa, risco, dados permitidos, revisão e evidência de respaldo.","Create a matrix of task, risk, permitted data, review, and supporting evidence."),e("Explica a stakeholders qué parte fue asistida y qué decisión mantuvo supervisión humana.","Explique a stakeholders qual parte foi assistida e qual decisão manteve supervisão humana.","Explain to stakeholders what was assisted and which decision retained human oversight.")),a("ai2",e("Diseñar experiencias con IA","Desenhar experiências com IA","Designing AI experiences"),e("Una experiencia con IA necesita comunicar capacidad, incertidumbre, control, privacidad, fuentes y vías de corrección.","Uma experiência com IA precisa comunicar capacidade, incerteza, controle, privacidade, fontes e caminhos de correção.","An AI experience must communicate capability, uncertainty, control, privacy, sources, and correction paths."),e("Presentar una salida generada como respuesta definitiva puede inducir sobreconfianza y daño.","Apresentar uma saída gerada como resposta definitiva pode induzir excesso de confiança e dano.","Presenting generated output as definitive can induce overtrust and harm."),e("Declara alcance, muestra origen cuando exista, permite editar o rechazar, ofrece fallback y prueba casos de error y sesgo.","Declare escopo, mostre origem quando existir, permita editar ou rejeitar, ofereça fallback e teste casos de erro e viés.","State scope, show origin where available, allow editing or rejection, offer fallback, and test error and bias cases."),e("Una sugerencia de texto debe permitir revisión y no enviar contenido sensible sin confirmación explícita.","Uma sugestão de texto deve permitir revisão e não enviar conteúdo sensível sem confirmação explícita.","A text suggestion should allow review and not send sensitive content without explicit confirmation."),e("Ocultar que una función genera contenido o hacer imposible corregirlo.","Ocultar que uma função gera conteúdo ou tornar impossível corrigi-lo.","Hiding that a feature generates content or making it impossible to correct."),e("Diseña un flujo de sugerencia con explicación, edición, descarte y registro de feedback.","Desenhe um fluxo de sugestão com explicação, edição, descarte e registro de feedback.","Design a suggestion flow with explanation, edit, dismissal, and feedback record."),e("Incluye escenarios de fallo, incertidumbre y exclusión en las pruebas de IA.","Inclua cenários de falha, incerteza e exclusão nos testes de IA.","Include failure, uncertainty, and exclusion scenarios in AI testing."))],quiz:i(e("¿Qué debe ocurrir después de una síntesis asistida por IA?","O que deve acontecer após uma síntese assistida por IA?","What should happen after AI-assisted synthesis?"),[e("Publicarla sin revisión","Publicá-la sem revisão","Publish it without review"),e("Verificarla contra fuentes, contexto y criterio humano","Verificá-la contra fontes, contexto e critério humano","Verify it against sources, context, and human judgment"),e("Eliminar las notas originales","Eliminar as notas originais","Delete the original notes")],1,e("La asistencia no sustituye trazabilidad ni evaluación humana.","A assistência não substitui rastreabilidade ou avaliação humana.","Assistance does not replace traceability or human assessment."))}),o({id:"portfolio",order:15,level:e("Nivel 15","Nível 15","Level 15"),title:e("Portfolio","Portfólio","Portfolio"),summary:e("Convierte el proceso en casos de estudio honestos que demuestran criterio, impacto, aprendizaje y colaboración.","Transforme o processo em estudos de caso honestos que demonstrem critério, impacto, aprendizagem e colaboração.","Turn process into honest case studies demonstrating judgment, impact, learning, and collaboration."),competencies:[e("Narrar decisiones","Narrar decisões","Narrate decisions"),e("Seleccionar evidencia","Selecionar evidências","Select evidence")],caseStudy:e("Un caso de estudio muestra veinte pantallas, pero no explica problema, rol, evidencia ni resultados. Rediseña su narrativa.","Um estudo de caso mostra vinte telas, mas não explica problema, papel, evidências ou resultados. Redesenhe sua narrativa.","A case study shows twenty screens but no problem, role, evidence, or results. Redesign its narrative."),guidedPractice:e("Ordena artefactos de proyecto desde contexto hasta resultado y elimina imágenes que no apoyan una decisión.","Ordene artefatos de projeto do contexto ao resultado e elimine imagens que não apoiam uma decisão.","Order project artifacts from context to result and remove images that do not support a decision."),individualPractice:e("Escribe la sección de iteración de un caso: qué cambió, por qué, qué evidencia lo motivó y qué sigue incierto.","Escreva a seção de iteração de um caso: o que mudou, por quê, que evidência motivou e o que permanece incerto.","Write a case-study iteration section: what changed, why, what evidence motivated it, and what remains uncertain."),miniProject:e("Publica un caso de estudio de Pulse con contexto, rol, proceso, decisiones, evidencia, resultado, límites y reflexión.","Publique um estudo de caso do Pulse com contexto, papel, processo, decisões, evidências, resultado, limites e reflexão.","Publish a Pulse case study with context, role, process, decisions, evidence, result, limits, and reflection."),rubricFocus:[e("Claridad narrativa","Clareza narrativa","Narrative clarity"),e("Honestidad de evidencia","Honestidade das evidências","Evidence honesty")],glossary:[{term:"Case study",definition:e("Narrativa estructurada de un problema, proceso, decisiones, evidencia y aprendizaje.","Narrativa estruturada de um problema, processo, decisões, evidências e aprendizagem.","Structured narrative of a problem, process, decisions, evidence, and learning.")}],lessons:[a("po1",e("Contar el problema antes del acabado","Contar o problema antes do acabamento","Tell the problem before the polish"),e("Un portfolio profesional muestra cómo piensas y colaboras, no solo el resultado visual final.","Um portfólio profissional mostra como você pensa e colabora, não apenas o resultado visual final.","A professional portfolio shows how you think and collaborate, not only final visual output."),e("Las imágenes sin contexto no permiten evaluar criterio, alcance, restricciones ni contribución real.","Imagens sem contexto não permitem avaliar critério, escopo, restrições ou contribuição real.","Images without context do not allow assessment of judgment, scope, constraints, or real contribution."),e("Enmarca situación, rol, equipo, objetivo, usuarios, evidencia, decisiones, resultados y reflexión en una secuencia escaneable.","Enquadre situação, papel, equipe, objetivo, usuários, evidências, decisões, resultados e reflexão em uma sequência escaneável.","Frame situation, role, team, goal, users, evidence, decisions, results, and reflection in a scannable sequence."),e("Una decisión de navegación vale más cuando explica el hallazgo que cambió la estructura.","Uma decisão de navegação vale mais quando explica o achado que mudou a estrutura.","A navigation decision matters more when it explains the finding that changed the structure."),e("Atribuirte resultados de equipo o inventar métricas para que el caso parezca más fuerte.","Atribuir a si resultados de equipe ou inventar métricas para que o caso pareça mais forte.","Claiming team results as your own or inventing metrics to make a case look stronger."),e("Redacta el resumen de proyecto en 120 palabras con rol, problema, decisión y evidencia.","Redija o resumo do projeto em 120 palavras com papel, problema, decisão e evidência.","Write a 120-word project summary with role, problem, decision, and evidence."),e("Prepara casos que resistan preguntas sobre qué hiciste, qué aprendiste y qué cambiarías.","Prepare casos que sustentem perguntas sobre o que fez, o que aprendeu e o que mudaria.","Prepare cases that withstand questions about what you did, learned, and would change.")),a("po2",e("Evidencia, límites y reflexión","Evidências, limites e reflexão","Evidence, limits, and reflection"),e("La credibilidad crece cuando el caso separa resultados observados, hipótesis, limitaciones y contribuciones compartidas.","A credibilidade cresce quando o caso separa resultados observados, hipóteses, limitações e contribuições compartilhadas.","Credibility grows when a case separates observed results, hypotheses, limitations, and shared contributions."),e("Una reflexión concreta demuestra aprendizaje y evita que el portfolio sea una galería sin razonamiento.","Uma reflexão concreta demonstra aprendizagem e evita que o portfólio seja uma galeria sem raciocínio.","Concrete reflection demonstrates learning and prevents the portfolio becoming a reasoning-free gallery."),e("Cita evidencia autorizada, protege confidencialidad, nombra límites y explica la siguiente decisión que tomarías.","Cite evidências autorizadas, proteja confidencialidade, nomeie limites e explique a próxima decisão que tomaria.","Cite authorized evidence, protect confidentiality, name limits, and explain the next decision you would make."),e("Si no hubo métricas post-lanzamiento, explica qué señales cualitativas existen y qué medirías después.","Se não houve métricas pós-lançamento, explique quais sinais qualitativos existem e o que mediria depois.","If there are no post-launch metrics, explain available qualitative signals and what you would measure next."),e("Ocultar decisiones fallidas aunque fueron clave para iterar.","Ocultar decisões falhas mesmo quando foram essenciais para iterar.","Hiding failed decisions even when they were key to iteration."),e("Añade una reflexión con limitación, aprendizaje y experimento siguiente.","Adicione uma reflexão com limitação, aprendizagem e próximo experimento.","Add a reflection with limitation, learning, and next experiment."),e("Revisa confidencialidad, accesibilidad y atribución antes de publicar un caso.","Revise confidencialidade, acessibilidade e atribuição antes de publicar um caso.","Review confidentiality, accessibility, and attribution before publishing a case."))],quiz:i(e("¿Qué fortalece un caso de estudio?","O que fortalece um estudo de caso?","What strengthens a case study?"),[e("Más pantallas sin explicación","Mais telas sem explicação","More screens without explanation"),e("Decisiones trazables a evidencia, límites y reflexión","Decisões rastreáveis a evidências, limites e reflexão","Decisions traceable to evidence, limits, and reflection"),e("Métricas inventadas","Métricas inventadas","Invented metrics")],1,e("La evidencia honesta permite valorar criterio y aprendizaje.","Evidência honesta permite avaliar critério e aprendizagem.","Honest evidence enables evaluation of judgment and learning."))}),o({id:"career-capstone",order:16,level:e("Nivel 16","Nível 16","Level 16"),title:e("Career & Capstone","Carreira & Capstone","Career & Capstone"),summary:e("Integra competencias en un problema abierto y prepara una comunicación profesional del trabajo realizado.","Integre competências em um problema aberto e prepare uma comunicação profissional do trabalho realizado.","Integrate competencies in an open problem and prepare a professional communication of the work completed."),competencies:[e("Defender decisiones","Defender decisões","Defend decisions"),e("Presentar un capstone","Apresentar um capstone","Present a capstone")],caseStudy:e("Un reto de acceso a formación adulta tiene partes interesadas, limitaciones de tiempo y datos incompletos. Define qué investigarías primero.","Um desafio de acesso à formação adulta tem partes interessadas, limitações de tempo e dados incompletos. Defina o que investigaria primeiro.","An adult-learning access challenge has stakeholders, time limits, and incomplete data. Define what you would investigate first."),guidedPractice:e("Responde un mini whiteboard challenge: aclara objetivo, usuarios, restricciones, flujo, medida y siguiente investigación en veinte minutos.","Responda a um mini whiteboard challenge: esclareça objetivo, usuários, restrições, fluxo, medida e próxima pesquisa em vinte minutos.","Respond to a mini whiteboard challenge: clarify goal, users, constraints, flow, measure, and next research in twenty minutes."),individualPractice:e("Ensaya una defensa de caso de siete minutos y registra una pregunta que aún no puedes responder con evidencia.","Ensaie uma defesa de caso de sete minutos e registre uma pergunta que ainda não pode responder com evidência.","Rehearse a seven-minute case defense and record a question you cannot yet answer with evidence."),miniProject:e("Completa el Capstone Open Brief y su defensa: research plan, hallazgos, definición, IA, wireframes, UI, sistema, test, iteración, caso y portfolio.","Complete o Capstone Open Brief e sua defesa: research plan, achados, definição, IA, wireframes, UI, sistema, teste, iteração, caso e portfólio.","Complete the Capstone Open Brief and defense: research plan, findings, definition, IA, wireframes, UI, system, test, iteration, case, and portfolio."),rubricFocus:[e("Integración de proceso","Integração de processo","Process integration"),e("Comunicación profesional","Comunicação profissional","Professional communication")],glossary:[{term:"Capstone",definition:e("Proyecto integrador que exige evidencias de competencias conectadas, no una solución predeterminada.","Projeto integrador que exige evidências de competências conectadas, não uma solução predeterminada.","Integrative project requiring evidence of connected competencies, not a predetermined solution.")}],lessons:[a("cc1",e("Comunicar bajo preguntas","Comunicar sob perguntas","Communicating under questions"),e("Una presentación profesional explica el problema, el rol, la evidencia, decisiones, trade-offs, resultado y aprendizaje con precisión.","Uma apresentação profissional explica o problema, papel, evidências, decisões, trade-offs, resultado e aprendizagem com precisão.","A professional presentation explains problem, role, evidence, decisions, trade-offs, result, and learning with precision."),e("Las entrevistas y revisiones evalúan cómo razonas ante incertidumbre, no solo si tu entrega parece terminada.","Entrevistas e revisões avaliam como você raciocina diante da incerteza, não apenas se sua entrega parece concluída.","Interviews and reviews evaluate how you reason under uncertainty, not only whether your delivery looks finished."),e("Organiza una narrativa breve, anticipa preguntas, declara límites y responde con evidencia o con un plan de aprendizaje.","Organize uma narrativa breve, antecipe perguntas, declare limites e responda com evidências ou plano de aprendizagem.","Organize a brief narrative, anticipate questions, state limits, and answer with evidence or a learning plan."),e("Ante '¿por qué este flujo?', relaciona la elección con tarea, hallazgo, restricción y prueba posterior.","Diante de 'por que este fluxo?', relacione a escolha com tarefa, achado, restrição e teste posterior.","When asked 'why this flow?', relate the choice to task, finding, constraint, and later test."),e("Responder con jerga o defender una elección como gusto personal.","Responder com jargão ou defender uma escolha como gosto pessoal.","Responding with jargon or defending a choice as personal taste."),e("Graba una defensa de tres minutos y marca afirmaciones que necesitan mejor evidencia.","Grave uma defesa de três minutos e marque afirmações que precisam de melhor evidência.","Record a three-minute defense and mark claims needing better evidence."),e("Adapta profundidad y lenguaje al público sin perder trazabilidad de decisiones.","Adapte profundidade e linguagem ao público sem perder rastreabilidade das decisões.","Adapt depth and language to audience without losing decision traceability.")),a("cc2",e("Capstone: integrar sin ocultar incertidumbre","Capstone: integrar sem ocultar incerteza","Capstone: integrate without hiding uncertainty"),e("El capstone demuestra una cadena de razonamiento desde una oportunidad hasta una propuesta evaluada y comunicada.","O capstone demonstra uma cadeia de raciocínio desde uma oportunidade até uma proposta avaliada e comunicada.","The capstone demonstrates a reasoning chain from opportunity through an evaluated, communicated proposal."),e("El criterio profesional no exige resolverlo todo; exige priorizar, declarar límites y elegir la siguiente evidencia responsable.","O critério profissional não exige resolver tudo; exige priorizar, declarar limites e escolher a próxima evidência responsável.","Professional judgment does not require solving everything; it requires prioritizing, stating limits, and choosing the next responsible evidence."),e("Planifica investigación, protege participantes, sintetiza, define, diseña, prueba, itera y documenta cada conexión entre evidencia y decisión.","Planeje pesquisa, proteja participantes, sintetize, defina, desenhe, teste, itere e documente cada conexão entre evidência e decisão.","Plan research, protect participants, synthesize, define, design, test, iterate, and document each link between evidence and decision."),e("Un test que contradice tu primera idea es evidencia de aprendizaje, no un fracaso que deba ocultarse.","Um teste que contradiz sua primeira ideia é evidência de aprendizagem, não um fracasso a esconder.","A test contradicting your first idea is evidence of learning, not failure to hide."),e("Fabricar investigación, participantes, métricas o resultados para cumplir una narrativa.","Fabricar pesquisa, participantes, métricas ou resultados para cumprir uma narrativa.","Fabricating research, participants, metrics, or results to fit a narrative."),e("Crea un índice de capstone que enlace cada artefacto con la pregunta que respondió.","Crie um índice de capstone que conecte cada artefato à pergunta que respondeu.","Create a capstone index linking every artifact to the question it answered."),e("Presenta tu capstone como evidencia de proceso, no como promesa de una solución perfecta.","Apresente seu capstone como evidência de processo, não como promessa de solução perfeita.","Present your capstone as evidence of process, not a promise of a perfect solution."))],quiz:i(e("¿Qué demuestra un capstone sólido?","O que demonstra um capstone sólido?","What demonstrates a strong capstone?"),[e("Una solución sin preguntas","Uma solução sem perguntas","A solution without questions"),e("Una cadena trazable entre evidencia, decisión, prueba y reflexión","Uma cadeia rastreável entre evidência, decisão, teste e reflexão","A traceable chain between evidence, decision, test, and reflection"),e("Una maqueta con muchos efectos","Uma maquete com muitos efeitos","A mockup with many effects")],1,e("El capstone se evalúa por razonamiento integrado, evidencia y comunicación responsable.","O capstone é avaliado por raciocínio integrado, evidências e comunicação responsável.","The capstone is evaluated for integrated reasoning, evidence, and responsible communication."))}));const f=[{category:e("Accesibilidad","Acessibilidade","Accessibility"),type:e("Oficial","Oficial","Official"),title:"W3C — WCAG 2 Overview",url:"https://www.w3.org/WAI/standards-guidelines/wcag/"},{category:e("Accesibilidad","Acessibilidade","Accessibility"),type:e("Oficial","Oficial","Official"),title:"W3C — Accessibility Tutorials",url:"https://www.w3.org/WAI/tutorials/"},{category:e("UI Design","UI Design","UI Design"),type:e("Oficial","Oficial","Official"),title:"Material Design 3",url:"https://m3.material.io/"},{category:e("UI Design","UI Design","UI Design"),type:e("Oficial","Oficial","Official"),title:"Apple Human Interface Guidelines",url:"https://developer.apple.com/design/human-interface-guidelines/"},{category:e("Design Systems","Design Systems","Design Systems"),type:e("Oficial","Oficial","Official"),title:"Figma — Guide to variables",url:"https://help.figma.com/hc/en-us/articles/15339657135383-Guide-to-variables-in-Figma"},{category:e("Figma","Figma","Figma"),type:e("Oficial","Oficial","Official"),title:"Figma — Guide to auto layout",url:"https://help.figma.com/hc/en-us/articles/360040451373-Guide-to-auto-layout"},{category:e("UX Research","UX Research","UX Research"),type:e("Educativa","Educacional","Educational"),title:"Nielsen Norman Group — Research methods",url:"https://www.nngroup.com/articles/which-ux-research-methods/"},{category:e("Usability Testing","Usability Testing","Usability Testing"),type:e("Educativa","Educacional","Educational"),title:"Nielsen Norman Group — Usability Testing 101",url:"https://www.nngroup.com/articles/usability-testing-101/"},{category:e("Product Design","Product Design","Product Design"),type:e("Complementaria","Complementar","Complementary"),title:"Design Council — Double Diamond",url:"https://www.designcouncil.org.uk/resources/the-double-diamond/"},{category:e("Product Design","Product Design","Product Design"),type:e("Complementaria","Complementar","Complementary"),title:"IDEO — Design Kit Methods",url:"https://www.designkit.org/methods.html"},{category:e("Accesibilidad","Acessibilidade","Accessibility"),type:e("Oficial","Oficial","Official"),title:"W3C — ARIA Authoring Practices Guide",url:"https://www.w3.org/WAI/ARIA/apg/"},{category:e("Accesibilidad","Acessibilidade","Accessibility"),type:e("Educativa","Educacional","Educational"),title:"GOV.UK Service Manual — Making your service accessible",url:"https://www.gov.uk/service-manual/helping-people-to-use-your-service/making-your-service-accessible-an-introduction"}];export{v as c,f as r,e as t};
